import { createResponse, handleCORS, handleError } from '../../utils/api-utils.js';

// Helper function for safe JSON parsing
async function safeJson(req) {
  try {
    return await req.json();
  } catch (error) {
    console.error('[safeJson] JSON parsing error:', error);
    throw new Error('Invalid JSON in request body');
  }
}

// Helper function for safe JSON parsing from string
function safeJsonParse(jsonString, defaultValue = null) {
  try {
    return JSON.parse(jsonString);
  } catch (error) {
    console.error('[safeJsonParse] JSON parsing error:', error);
    return defaultValue;
  }
}

export async function onRequest(context) {
  const { request, env } = context;
  
  // Handle CORS preflight
  if (request.method === 'OPTIONS') {
    return handleCORS();
  }
  
  try {
    switch (request.method) {
      case 'POST':
        return await handleGenerateSummary(request, env);
      case 'PUT':
          return await handleRefineeSummary(request, env);
        default:
          return handleError(`Method not allowed: ${request.method}`, 405);
      }
    } catch (error) {
      return handleError(error);
    }
  }
/**
 * Handle POST requests - generate AI-powered clinical summary
 */
async function handleGenerateSummary(request, env) {
  try {
    const data = await safeJson(request);
    const { formData, templateId, summaryType = 'comprehensive' } = data;
    
    // Validate required fields
    if (!formData) {
      return handleError('Form data is required', 400);
    }
    
    // Extract clinical data for AI processing
    const clinicalContext = extractClinicalContext(formData);
    
    // Generate AI prompt based on clinical context
    const prompt = generateClinicalPrompt(clinicalContext, summaryType);
    
    // Call Cloudflare Workers AI
    const aiResponse = await generateAISummary(env, prompt, clinicalContext);
    
    if (!aiResponse.success) {
      return handleError(aiResponse.error, 502); // 502 Bad Gateway from AI service
    }
    
    // Structure the AI response into clinical sections
    const structuredSummary = structureAIResponse(aiResponse.summary, clinicalContext);
    
    // Store AI summary in database for future reference and refinement
    const summaryId = await storeAISummary(env, {
      userId: 'anonymous', // Default user ID since auth is removed
      templateId,
      formData: JSON.stringify(formData),
      aiPrompt: prompt,
      aiResponse: aiResponse.summary,
      structuredSummary: JSON.stringify(structuredSummary),
      summaryType,
      timestamp: new Date().toISOString()
    });
    
    return createResponse({
      success: true,
      message: 'AI summary generated successfully',
      data: {
        summaryId,
        summary: structuredSummary,
        metadata: {
          model: aiResponse.model,
          tokenCount: aiResponse.tokenCount,
          processingTime: aiResponse.processingTime
        }
      }
    });
    
  } catch (error) {
    return handleError(error, 'Failed to generate AI summary');
  }
}

/**
 * Handle PUT requests - refine existing AI summary based on clinician feedback
 */
async function handleRefineeSummary(request, env) {
  try {
    const data = await safeJson(request);
    const { summaryId, feedback, refinementType = 'correction' } = data;
    
    if (!summaryId || !feedback) {
      return handleError('Summary ID and feedback are required', 400);
    }
    
    // Get original summary (removed user_id check since auth is removed)
    const originalSummary = await env.DB.prepare(`
      SELECT * FROM ai_summaries WHERE id = ?
    `).bind(summaryId).first();
    
    if (!originalSummary) {
      return handleError('Summary not found', 404);
    }
    
    // Parse original data
    const originalData = safeJsonParse(originalSummary.form_data, {});
    if (!originalData || Object.keys(originalData).length === 0) {
      return handleError('Invalid form data in original summary', 400);
    }
    const clinicalContext = extractClinicalContext(originalData);
    
    // Generate refinement prompt
    const refinementPrompt = generateRefinementPrompt(
      originalSummary.ai_response,
      feedback,
      refinementType,
      clinicalContext
    );
    
    // Call AI for refinement
    const aiResponse = await generateAISummary(env, refinementPrompt, clinicalContext);
    
    if (!aiResponse.success) {
      return handleError(aiResponse.error, 502); // 502 Bad Gateway from AI service
    }
    
    // Structure refined response
    const refinedSummary = structureAIResponse(aiResponse.summary, clinicalContext);
    
    // Store refinement
    await env.DB.prepare(`
      UPDATE ai_summaries 
      SET ai_response = ?, structured_summary = ?, refinement_count = refinement_count + 1, updated_at = ?
      WHERE id = ?
    `).bind(
      aiResponse.summary,
      JSON.stringify(refinedSummary),
      new Date().toISOString(),
      summaryId
    ).run();
    
    // Store feedback for learning
    await storeClinicalFeedback(env, {
      summaryId,
      userId: 'anonymous', // Default user ID since auth is removed
      feedback,
      refinementType,
      originalResponse: originalSummary.ai_response,
      refinedResponse: aiResponse.summary
    });
    
    return createResponse({
      success: true,
      message: 'AI summary refined successfully',
      data: {
        summaryId,
        summary: refinedSummary,
        metadata: {
          model: aiResponse.model,
          tokenCount: aiResponse.tokenCount,
          processingTime: aiResponse.processingTime,
          refinementType
        }
      }
    });
    
  } catch (error) {
    return handleError(error, 'Failed to refine AI summary');
  }
}

/**
 * Extract clinical context from form data for AI processing
 */
function extractClinicalContext(formData) {
  return {
    // Patient Demographics
    patientInfo: {
      name: `${formData.firstName || ''} ${formData.lastName || ''}`.trim(),
      age: formData.age,
      gender: formData.gender,
      school: formData.school,
      grade: formData.grade
    },
    
    // Evaluation Context
    evaluationInfo: {
      date: formData.evaluationDate,
      place: formData.placeOfEvaluation,
      screening: formData.screening === 'true',
      screeningDate: formData.screeningDate,
      organization: formData.organization,
      areas: formData.evaluationAreas || []
    },
    
    // Assessment Scores (PLS-5)
    assessmentScores: {
      auditoryComprehension: {
        standardScore: formData.ac_standard_score,
        ageEquivalent: formData.ac_age_equivalent,
        percentile: formData.ac_percentile,
        confidenceInterval: formData.ac_confidence_interval
      },
      expressiveCommunication: {
        standardScore: formData.ec_standard_score,
        ageEquivalent: formData.ec_age_equivalent,
        percentile: formData.ec_percentile,
        confidenceInterval: formData.ec_confidence_interval
      },
      totalLanguage: {
        standardScore: formData.tl_standard_score,
        ageEquivalent: formData.tl_age_equivalent,
        percentile: formData.tl_percentile,
        confidenceInterval: formData.tl_confidence_interval
      }
    },
    
    // Clinical Observations
    clinicalObservations: {
      strengths: extractCheckedItems(formData, 'strength_'),
      expressiveStrengths: extractCheckedItems(formData, 'expressive_strength_'),
      difficulties: extractCheckedItems(formData, 'difficulty_'),
      behavioralObservations: {
        classroomTransition: formData.classroom_transition === 'true',
        nameResponse: formData.name_response === 'true',
        jointAttention: formData.joint_attention === 'true',
        eyeContact: formData.eye_contact === 'true',
        communicativeIntent: formData.communicative_intent === 'true',
        attention: formData.attention === 'true'
      }
    },
    
    // Speech Sound Production
    speechProduction: {
      intelligibilityNotes: formData.intelligibilityNotes,
      articulationErrors: extractArticulationErrors(formData)
    },
    
    // Language Sample
    languageSample: {
      structure: formData.languageStructure,
      content: formData.languageContent,
      socialLanguage: formData.socialLanguage
    }
  };
}

/**
 * Generate clinical AI prompt for summary generation
 */
function generateClinicalPrompt(clinicalContext, summaryType) {
  const { patientInfo, evaluationInfo, assessmentScores, clinicalObservations } = clinicalContext;
  
  const basePrompt = `You are a certified speech-language pathologist writing a professional clinical evaluation summary. Generate a comprehensive, evidence-based evaluation report for:

PATIENT: ${patientInfo.name}, ${patientInfo.age} years old, ${patientInfo.gender}
EVALUATION DATE: ${evaluationInfo.date}
SETTING: ${evaluationInfo.place}

ASSESSMENT RESULTS (PLS-5):
- Auditory Comprehension: Standard Score ${assessmentScores.auditoryComprehension.standardScore}, Age Equivalent ${assessmentScores.auditoryComprehension.ageEquivalent}
- Expressive Communication: Standard Score ${assessmentScores.expressiveCommunication.standardScore}, Age Equivalent ${assessmentScores.expressiveCommunication.ageEquivalent}  
- Total Language: Standard Score ${assessmentScores.totalLanguage.standardScore}, Age Equivalent ${assessmentScores.totalLanguage.ageEquivalent}

CLINICAL OBSERVATIONS:
- Strengths: ${clinicalObservations.strengths.join(', ')}
- Areas of Difficulty: ${clinicalObservations.difficulties.join(', ')}

Please generate a professional clinical summary that includes:
1. Introduction with patient demographics and evaluation context
2. Assessment results interpretation with score analysis
3. Behavioral observations and clinical impressions
4. Evidence-based recommendations for intervention

Use professional clinical language appropriate for a speech-language pathology evaluation report. Ensure all interpretations are evidence-based and follow current clinical standards.`;

  if (summaryType === 'brief') {
    return basePrompt + '\n\nGenerate a BRIEF summary (2-3 paragraphs maximum) focusing on key findings and primary recommendations.';
  }
  
  return basePrompt + '\n\nGenerate a COMPREHENSIVE evaluation summary with detailed analysis of all assessment domains.';
}

/**
 * Generate refinement prompt for clinician feedback
 */
function generateRefinementPrompt(originalSummary, feedback, refinementType, clinicalContext) {
  return `You are refining a clinical speech-language evaluation summary based on professional feedback.

ORIGINAL SUMMARY:
${originalSummary}

CLINICIAN FEEDBACK (${refinementType}):
${feedback}

PATIENT CONTEXT: ${clinicalContext.patientInfo.name}, ${clinicalContext.patientInfo.age} years old

Please revise the summary incorporating the clinician's feedback while maintaining professional clinical standards and evidence-based interpretations. Ensure the revised summary is accurate, comprehensive, and follows speech-language pathology documentation standards.`;
}

/**
 * Call Cloudflare Workers AI for summary generation
 */
async function generateAISummary(env, prompt, clinicalContext) {
  try {
    const startTime = Date.now();
    
    // Use Llama 3.3 70B for clinical text generation
    const response = await env.AI.run('@cf/meta/llama-3.3-70b-instruct', {
      messages: [
        {
          role: 'system',
          content: 'You are a certified speech-language pathologist with expertise in clinical evaluation and documentation. Provide professional, evidence-based clinical summaries following ASHA guidelines.'
        },
        {
          role: 'user',
          content: prompt
        }
      ],
      max_tokens: 2048,
      temperature: 0.3, // Lower temperature for clinical consistency
      top_p: 0.9
    });
    
    const processingTime = Date.now() - startTime;
    
    if (!response || !response.response) {
      throw new Error('Invalid AI response');
    }
    
    return {
      success: true,
      summary: response.response,
      model: '@cf/meta/llama-3.3-70b-instruct',
      tokenCount: estimateTokenCount(prompt + response.response),
      processingTime
    };
    
  } catch (error) {
    console.error('AI generation error:', error);
    return {
      success: false,
      error: `AI generation failed: ${error.message}`
    };
  }
}

/**
 * Structure AI response into clinical sections
 */
function structureAIResponse(aiSummary, clinicalContext) {
  // Basic structure - could be enhanced with more sophisticated parsing
  return {
    fullSummary: aiSummary,
    patientInfo: clinicalContext.patientInfo,
    evaluationDate: clinicalContext.evaluationInfo.date,
    assessmentScores: clinicalContext.assessmentScores,
    generatedAt: new Date().toISOString(),
    aiGenerated: true
  };
}

/**
 * Store AI summary in database
 */
async function storeAISummary(env, summaryData) {
  try {
    const result = await env.DB.prepare(`
      INSERT INTO ai_summaries (user_id, template_id, form_data, ai_prompt, ai_response, structured_summary, summary_type, created_at, updated_at, refinement_count)
      VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, 0)
    `).bind(
      summaryData.userId,
      summaryData.templateId,
      summaryData.formData,
      summaryData.aiPrompt,
      summaryData.aiResponse,
      summaryData.structuredSummary,
      summaryData.summaryType,
      summaryData.timestamp,
      summaryData.timestamp
    ).run();
    
    return result.meta.last_row_id;
  } catch (error) {
    console.error('Store AI summary error:', error);
    throw error;
  }
}

/**
 * Store clinical feedback for learning
 */
async function storeClinicalFeedback(env, feedbackData) {
  try {
    await env.DB.prepare(`
      INSERT INTO ai_feedback (summary_id, user_id, feedback, refinement_type, original_response, refined_response, created_at)
      VALUES (?, ?, ?, ?, ?, ?, ?)
    `).bind(
      feedbackData.summaryId,
      feedbackData.userId,
      feedbackData.feedback,
      feedbackData.refinementType,
      feedbackData.originalResponse,
      feedbackData.refinedResponse,
      new Date().toISOString()
    ).run();
  } catch (error) {
    console.error('Store feedback error:', error);
    // Don't throw - feedback storage is supplementary
  }
}

/**
 * Helper function to extract checked items
 */
function extractCheckedItems(formData, prefix) {
  return Object.entries(formData)
    .filter(([key, value]) => key.startsWith(prefix) && value === true)
    .map(([key]) => key.replace(prefix, '').replace(/_/g, ' '));
}

/**
 * Helper function to extract articulation errors
 */
function extractArticulationErrors(formData) {
  const errors = [];
  const sounds = ['p', 't', 'k', 'b', 'm', 'n', 'g', 'h', 'w', 'j'];
  
  for (const sound of sounds) {
    if (formData[`sound_${sound}_misarticulated`]) {
      errors.push({
        sound: `/${sound}/`,
        substitution: formData[`sound_${sound}_type`],
        position: formData[`sound_${sound}_position`],
        detail: formData[`sound_${sound}_detail`]
      });
    }
  }
  
  return errors;
}

/**
 * Estimate token count for cost tracking
 */
function estimateTokenCount(text) {
  // Rough estimation: ~4 characters per token
  return Math.ceil(text.length / 4);
}

import { createResponse, handleCORS, handleError } from '../../utils/api-utils.js';

export async function onRequest(request, env, context) {
  
  // Handle CORS preflight
  if (request.method === 'OPTIONS') {
    return handleCORS();
  }
  
  try {
    const url = new URL(request.url);
    
    switch (request.method) {
      case 'GET':
        return await handleGetAnalytics(env, url.searchParams);
      case 'POST':
          return await handleTrackEvent(request, env);
        default:
          return handleError(`Method not allowed: ${request.method}`, 405);
      }
    } catch (error) {
      return handleError(error);
    }
  }
/**
 * Handle GET requests - retrieve analytics data
 */
async function handleGetAnalytics(env, searchParams) {
  const type = searchParams.get('type') || 'overview';
  const templateId = searchParams.get('template_id');
  const startDate = searchParams.get('start_date');
  const endDate = searchParams.get('end_date');
  const timeframe = searchParams.get('timeframe') || '30d'; // 7d, 30d, 90d, 1y
  
  try {
    switch (type) {
      case 'overview':
        return await getOverviewAnalytics(env, timeframe, startDate, endDate);
      case 'template':
        if (!templateId) {
          return handleError('Template ID is required for template analytics', 400);
        }
        return await getTemplateAnalytics(env, templateId, timeframe, startDate, endDate);
      case 'submissions':
        return await getSubmissionAnalytics(env, templateId, timeframe, startDate, endDate);
      case 'users':
        return await getUserAnalytics(env, timeframe, startDate, endDate);
      case 'performance':
        return await getPerformanceAnalytics(env, templateId, timeframe, startDate, endDate);
      default:
        return handleError('Invalid analytics type', 400);
    }
  } catch (error) {
    return handleError(error, 'Failed to retrieve analytics');
  }
}

/**
 * Handle POST requests - track analytics events
 */
async function handleTrackEvent(request, env) {
  try {
    const data = await request.json();
    const { event_type, template_id, metadata } = data;
    
    if (!event_type) {
      return handleError('Event type is required', 400);
    }
    
    const now = new Date().toISOString();
    
    // Insert analytics event - use "Anonymous" as user_id for open access
    const result = await env.DB.prepare(`
      INSERT INTO analytics_events (event_type, template_id, user_id, timestamp, metadata)
      VALUES (?, ?, ?, ?, ?)
    `).bind(
      event_type,
      template_id || null,
      'anonymous', // Anonymous user for open access
      now,
      metadata ? JSON.stringify(metadata) : null
    ).run();

    return createResponse({ event_id: result.meta.last_row_id }, 201);
  } catch (error) {
    return handleError(error, 'Failed to track event');
  }
}

/**
 * Get overview analytics - system-wide data without user restrictions
 */
async function getOverviewAnalytics(env, timeframe, startDate, endDate) {
  const dateRange = getDateRange(timeframe, startDate, endDate);
  
  // Total statistics - system-wide
  const totalStats = await env.DB.prepare(`
    SELECT
      (SELECT COUNT(*) FROM form_templates) as total_templates,
      (SELECT COUNT(*) FROM form_submissions WHERE submitted_at >= ? AND submitted_at <= ?) as total_submissions,
      (SELECT COUNT(DISTINCT submitted_by) FROM form_submissions WHERE submitted_at >= ? AND submitted_at <= ?) as active_users,
      (SELECT COUNT(*) FROM users WHERE role = 'user') as total_users
  `).bind(dateRange.start, dateRange.end, dateRange.start, dateRange.end).first();
  
  // Submission trends (daily) - all submissions
  const submissionTrends = await env.DB.prepare(`
    SELECT 
      DATE(submitted_at) as date,
      COUNT(*) as count
    FROM form_submissions 
    WHERE submitted_at >= ? AND submitted_at <= ?
    GROUP BY DATE(submitted_at)
    ORDER BY date
  `).bind(dateRange.start, dateRange.end).all();
  
  // Top templates by submissions - all templates
  const topTemplates = await env.DB.prepare(`
    SELECT
      ft.id,
      ft.name,
      COUNT(fs.id) as submission_count,
      AVG(fs.score) as average_score
    FROM form_templates ft
    LEFT JOIN form_submissions fs ON ft.id = fs.template_id
      AND fs.submitted_at >= ? AND fs.submitted_at <= ?
    GROUP BY ft.id, ft.name
    ORDER BY submission_count DESC
    LIMIT 10
  `).bind(dateRange.start, dateRange.end).all();
  
  // User activity distribution - all users
  const userActivity = await env.DB.prepare(`
    SELECT 
      u.role,
      COUNT(DISTINCT u.id) as user_count,
      COUNT(fs.id) as submission_count
    FROM users u
    LEFT JOIN form_submissions fs ON u.id = fs.submitted_by 
      AND fs.submitted_at >= ? AND fs.submitted_at <= ?
    GROUP BY u.role
  `).bind(dateRange.start, dateRange.end).all();
  
  return createResponse({
    success: true,
    data: {
      stats: totalStats,
      trends: {
        submissions: submissionTrends.results || []
      },
      top_templates: topTemplates.results || [],
      user_activity: userActivity.results || [],
      date_range: dateRange
    }
  });
}

/**
 * Get template-specific analytics - open access
 */
async function getTemplateAnalytics(env, templateId, timeframe, startDate, endDate) {
  const dateRange = getDateRange(timeframe, startDate, endDate);
  
  // Template info and stats
  const templateInfo = await env.DB.prepare(`
    SELECT 
      ft.*,
      'Anonymous' as creator_name,
      COUNT(fs.id) as total_submissions,
      AVG(fs.score) as average_score,
      MIN(fs.score) as min_score,
      MAX(fs.score) as max_score
    FROM form_templates ft
    LEFT JOIN form_submissions fs ON ft.id = fs.template_id
      AND fs.submitted_at >= ? AND fs.submitted_at <= ?
    WHERE ft.id = ?
    GROUP BY ft.id
  `).bind(dateRange.start, dateRange.end, templateId).first();
  
  if (!templateInfo) {
    return handleError('Template not found', 404);
  }
  
  // Submission timeline - all submissions for this template
  const submissionTimeline = await env.DB.prepare(`
    SELECT 
      DATE(submitted_at) as date,
      COUNT(*) as submissions,
      AVG(score) as average_score
    FROM form_submissions 
    WHERE template_id = ? AND submitted_at >= ? AND submitted_at <= ?
    GROUP BY DATE(submitted_at)
    ORDER BY date
  `).bind(templateId, dateRange.start, dateRange.end).all();
  
  // Score distribution - all scores for this template
  const scoreDistribution = await env.DB.prepare(`
    SELECT 
      CASE 
        WHEN score >= 90 THEN '90-100'
        WHEN score >= 80 THEN '80-89'
        WHEN score >= 70 THEN '70-79'
        WHEN score >= 60 THEN '60-69'
        WHEN score >= 50 THEN '50-59'
        ELSE '0-49'
      END as score_range,
      COUNT(*) as count
    FROM form_submissions 
    WHERE template_id = ? AND submitted_at >= ? AND submitted_at <= ? AND score IS NOT NULL
    GROUP BY score_range
    ORDER BY score_range DESC
  `).bind(templateId, dateRange.start, dateRange.end).all();
  
  // Completion stats - all submissions for this template
  const completionStats = await env.DB.prepare(`
    SELECT 
      status,
      COUNT(*) as count
    FROM form_submissions 
    WHERE template_id = ? AND submitted_at >= ? AND submitted_at <= ?
    GROUP BY status
  `).bind(templateId, dateRange.start, dateRange.end).all();
  
  // Recent submissions - all recent submissions for this template
  const recentSubmissions = await env.DB.prepare(`
    SELECT 
      fs.id,
      fs.score,
      fs.status,
      fs.submitted_at,
      'Anonymous' as submitter_name,
      'anonymous@example.com' as submitter_email
    FROM form_submissions fs
    WHERE fs.template_id = ? AND fs.submitted_at >= ? AND fs.submitted_at <= ?
    ORDER BY fs.submitted_at DESC
    LIMIT 20
  `).bind(templateId, dateRange.start, dateRange.end).all();
  
  return createResponse({
    success: true,
    data: {
      template: templateInfo,
      timeline: submissionTimeline.results || [],
      score_distribution: scoreDistribution.results || [],
      completion_stats: completionStats.results || [],
      recent_submissions: recentSubmissions.results || [],
      date_range: dateRange
    }
  });
}

/**
 * Get submission analytics - system-wide data
 */
async function getSubmissionAnalytics(env, templateId, timeframe, startDate, endDate) {
  const dateRange = getDateRange(timeframe, startDate, endDate);
  
  let whereClause = 'WHERE fs.submitted_at >= ? AND fs.submitted_at <= ?';
  let params = [dateRange.start, dateRange.end];
  
  if (templateId) {
    whereClause += ' AND fs.template_id = ?';
    params.push(templateId);
  }
  
  // Submission volume trends - all submissions
  const volumeTrends = await env.DB.prepare(`
    SELECT 
      DATE(fs.submitted_at) as date,
      COUNT(*) as total_submissions,
      COUNT(CASE WHEN fs.status = 'completed' THEN 1 END) as completed_submissions,
      AVG(fs.score) as average_score
    FROM form_submissions fs
    ${whereClause}
    GROUP BY DATE(fs.submitted_at)
    ORDER BY date
  `).bind(...params).all();
  
  // Time-to-completion analysis - all submissions
  const timeAnalysis = await env.DB.prepare(`
    SELECT 
      AVG(JULIANDAY(fs.submitted_at) - JULIANDAY(ae.timestamp)) * 24 * 60 as avg_completion_time_minutes,
      COUNT(*) as sample_size
    FROM form_submissions fs
    JOIN analytics_events ae ON fs.template_id = ae.template_id 
      AND ae.event_type = 'form_started'
      AND ae.timestamp <= fs.submitted_at
    ${whereClause.replace('fs.submitted_at', 'fs.submitted_at')}
  `).bind(...params).first();
  
  // Popular submission times - all submissions
  const timeDistribution = await env.DB.prepare(`
    SELECT 
      CASE 
        WHEN CAST(strftime('%H', submitted_at) AS INTEGER) BETWEEN 6 AND 11 THEN 'Morning (6-11)'
        WHEN CAST(strftime('%H', submitted_at) AS INTEGER) BETWEEN 12 AND 17 THEN 'Afternoon (12-17)'
        WHEN CAST(strftime('%H', submitted_at) AS INTEGER) BETWEEN 18 AND 21 THEN 'Evening (18-21)'
        ELSE 'Night (22-5)'
      END as time_period,
      COUNT(*) as count
    FROM form_submissions fs
    ${whereClause}
    GROUP BY time_period
  `).bind(...params).all();
  
  // User engagement metrics - system-wide
  const engagementMetrics = await env.DB.prepare(`
    SELECT 
      COUNT(DISTINCT fs.submitted_by) as unique_users,
      COUNT(*) as total_submissions,
      COUNT(*) * 1.0 / COUNT(DISTINCT fs.submitted_by) as avg_submissions_per_user,
      COUNT(CASE WHEN user_submission_count.submission_count > 1 THEN 1 END) as returning_users
    FROM form_submissions fs
    JOIN (
      SELECT 
        submitted_by, 
        COUNT(*) as submission_count
      FROM form_submissions 
      ${whereClause.replace('fs.', '')}
      GROUP BY submitted_by
    ) user_submission_count ON fs.submitted_by = user_submission_count.submitted_by
    ${whereClause}
  `).bind(...params, ...params).first();
  
  return createResponse(true, 'Submission analytics retrieved', {
    volume_trends: volumeTrends.results || [],
    time_analysis: timeAnalysis,
    time_distribution: timeDistribution.results || [],
    engagement_metrics: engagementMetrics,
    date_range: dateRange
  });
}

/**
 * Get user analytics - system-wide data
 */
async function getUserAnalytics(env, timeframe, startDate, endDate) {
  const dateRange = getDateRange(timeframe, startDate, endDate);
  
  // User registration trends - all users
  const registrationTrends = await env.DB.prepare(`
    SELECT 
      DATE(created_at) as date,
      COUNT(*) as new_users
    FROM users 
    WHERE created_at >= ? AND created_at <= ?
    GROUP BY DATE(created_at)
    ORDER BY date
  `).bind(dateRange.start, dateRange.end).all();
  
  // User role distribution - all users
  const roleDistribution = await env.DB.prepare(`
    SELECT 
      role,
      COUNT(*) as count
    FROM users
    GROUP BY role
  `).bind().all();
  
  // Most active users - all users
  const activeUsers = await env.DB.prepare(`
    SELECT 
      'Anonymous' as name,
      'anonymous@example.com' as email,
      'user' as role,
      COUNT(fs.id) as submission_count,
      AVG(fs.score) as average_score,
      MAX(fs.submitted_at) as last_submission
    FROM form_submissions fs
    WHERE fs.submitted_at >= ? AND fs.submitted_at <= ?
    GROUP BY fs.submitted_by
    HAVING submission_count > 0
    ORDER BY submission_count DESC, average_score DESC
    LIMIT 20
  `).bind(dateRange.start, dateRange.end).all();
  
  // User activity patterns - all users
  const activityPatterns = await env.DB.prepare(`
    SELECT 
      strftime('%w', fs.submitted_at) as day_of_week,
      strftime('%H', fs.submitted_at) as hour_of_day,
      COUNT(*) as activity_count
    FROM form_submissions fs
    WHERE fs.submitted_at >= ? AND fs.submitted_at <= ?
    GROUP BY day_of_week, hour_of_day
    ORDER BY activity_count DESC
  `).bind(dateRange.start, dateRange.end).all();
  
  return createResponse({
    success: true,
    data: {
      registration_trends: registrationTrends.results || [],
      role_distribution: roleDistribution.results || [],
      active_users: activeUsers.results || [],
      activity_patterns: activityPatterns.results || [],
      date_range: dateRange
    }
  });
}

/**
 * Get performance analytics - system-wide data
 */
async function getPerformanceAnalytics(env, templateId, timeframe, startDate, endDate) {
  const dateRange = getDateRange(timeframe, startDate, endDate);
  
  let whereClause = 'WHERE ae.timestamp >= ? AND ae.timestamp <= ?';
  let params = [dateRange.start, dateRange.end];
  
  if (templateId) {
    whereClause += ' AND ae.template_id = ?';
    params.push(templateId);
  }
  
  // Event distribution - all events
  const eventDistribution = await env.DB.prepare(`
    SELECT 
      event_type,
      COUNT(*) as count
    FROM analytics_events ae
    ${whereClause}
    GROUP BY event_type
    ORDER BY count DESC
  `).bind(...params).all();
  
  // Template performance comparison - all templates
  const templatePerformance = await env.DB.prepare(`
    SELECT
      ft.id,
      ft.name,
      COUNT(CASE WHEN ae.event_type = 'form_started' THEN 1 END) as starts,
      COUNT(CASE WHEN ae.event_type = 'form_submission' THEN 1 END) as completions,
      CASE
        WHEN COUNT(CASE WHEN ae.event_type = 'form_started' THEN 1 END) > 0
        THEN (COUNT(CASE WHEN ae.event_type = 'form_submission' THEN 1 END) * 100.0 /
              COUNT(CASE WHEN ae.event_type = 'form_started' THEN 1 END))
        ELSE 0
      END as completion_rate,
      AVG(fs.score) as average_score
    FROM form_templates ft
    LEFT JOIN analytics_events ae ON ft.id = ae.template_id
      AND ae.timestamp >= ? AND ae.timestamp <= ?
    LEFT JOIN form_submissions fs ON ft.id = fs.template_id
      AND fs.submitted_at >= ? AND fs.submitted_at <= ?
    GROUP BY ft.id, ft.name
    ORDER BY completion_rate DESC, starts DESC
  `).bind(dateRange.start, dateRange.end, dateRange.start, dateRange.end).all();
  
  // Error tracking - all errors
  const errorEvents = await env.DB.prepare(`
    SELECT 
      DATE(ae.timestamp) as date,
      COUNT(*) as error_count,
      ae.metadata
    FROM analytics_events ae
    WHERE ae.event_type = 'form_error' 
      AND ae.timestamp >= ? AND ae.timestamp <= ?
    GROUP BY DATE(ae.timestamp), ae.metadata
    ORDER BY date DESC
  `).bind(dateRange.start, dateRange.end).all();
  
  return createResponse({
    success: true,
    data: {
      event_distribution: eventDistribution.results || [],
      template_performance: templatePerformance.results || [],
      error_events: errorEvents.results || [],
      date_range: dateRange
    }
  });
}

/**
 * Calculate date range based on timeframe
 */
function getDateRange(timeframe, startDate, endDate) {
  const now = new Date();
  let start, end;
  
  if (startDate && endDate) {
    start = new Date(startDate);
    end = new Date(endDate);
  } else {
    end = now;
    
    switch (timeframe) {
      case '7d':
        start = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
        break;
      case '30d':
        start = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
        break;
      case '90d':
        start = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
        break;
      case '1y':
        start = new Date(now.getTime() - 365 * 24 * 60 * 60 * 1000);
        break;
      default:
        start = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    }
  }
  
  return {
    start: start.toISOString(),
    end: end.toISOString()
  };
}

