import { createResponse, handleCORS } from '../../auth/utils.js';

export async function onRequest(context) {
  const { request } = context;
  
  // Handle CORS preflight
  if (request.method === 'OPTIONS') {
    return handleCORS();
  }
  
  // Return message that authentication is disabled
  return createResponse(false, 'Session management has been disabled. This system now operates in open-access mode.', null, 200);
}

import { verifyToken, createResponse } from './utils.js';

/**
 * Authentication middleware for Cloudflare Functions
 * Verifies JWT tokens and user sessions
 */
export async function authenticateUser(request, env) {
  try {
    // Get token from Authorization header or cookies
    const authHeader = request.headers.get('Authorization');
    let token = null;
    
    if (authHeader && authHeader.startsWith('Bearer ')) {
      token = authHeader.substring(7);
    } else {
      // Try to get token from cookies
      const cookieHeader = request.headers.get('Cookie');
      if (cookieHeader) {
        const cookies = cookieHeader.split(';').reduce((acc, cookie) => {
          const [key, value] = cookie.trim().split('=');
          acc[key] = value;
          return acc;
        }, {});
        token = cookies.auth_token;
      }
    }
    
    if (!token) {
      return {
        success: false,
        error: 'No authentication token provided',
        statusCode: 401
      };
    }
    
    // Verify JWT token
    const decoded = verifyToken(token, env.JWT_SECRET);
    if (!decoded) {
      return {
        success: false,
        error: 'Invalid or expired token',
        statusCode: 401
      };
    }
    
    // Check if session exists in KV store
    const sessionKey = `session:${decoded.id}`;
    const sessionData = await env.SESSIONS.get(sessionKey);
    
    if (!sessionData) {
      return {
        success: false,
        error: 'Session not found or expired',
        statusCode: 401
      };
    }
    
    const session = JSON.parse(sessionData);
    
    // Verify session is still valid
    if (session.expires < Date.now()) {
      // Clean up expired session
      await env.SESSIONS.delete(sessionKey);
      return {
        success: false,
        error: 'Session expired',
        statusCode: 401
      };
    }
    
    // Get user data from database
    const db = env.DB;
    const user = await db.prepare('SELECT id, email, role, first_name, last_name, created_at FROM users WHERE id = ?')
      .bind(decoded.id)
      .first();
    
    if (!user) {
      return {
        success: false,
        error: 'User not found',
        statusCode: 404
      };
    }
    
    return {
      success: true,
      user: {
        id: user.id,
        email: user.email,
        role: user.role,
        firstName: user.first_name,
        lastName: user.last_name,
        createdAt: user.created_at
      },
      session: {
        id: session.id,
        expires: session.expires
      }
    };
    
  } catch (error) {
    console.error('Authentication error:', error);
    return {
      success: false,
      error: 'Authentication failed',
      statusCode: 500
    };
  }
}

/**
 * Middleware to require authentication for a route
 * Returns authenticated user or error response
 */
export async function requireAuth(request, env) {
  const authResult = await authenticateUser(request, env);
  
  if (!authResult.success) {
    return createResponse(
      false,
      authResult.error,
      null,
      authResult.statusCode
    );
  }
  
  return authResult;
}

/**
 * Middleware to require admin role
 * Returns authenticated admin user or error response
 */
export async function requireAdmin(request, env) {
  const authResult = await authenticateUser(request, env);
  
  if (!authResult.success) {
    return createResponse(
      false,
      authResult.error,
      null,
      authResult.statusCode
    );
  }
  
  if (authResult.user.role !== 'admin') {
    return createResponse(
      false,
      'Admin access required',
      null,
      403
    );
  }
  
  return authResult;
}

/**
 * Middleware to require clinician role or higher
 * Returns authenticated clinician/admin user or error response
 */
export async function requireClinician(request, env) {
  const authResult = await authenticateUser(request, env);
  
  if (!authResult.success) {
    return createResponse(
      false,
      authResult.error,
      null,
      authResult.statusCode
    );
  }
  
  if (!['clinician', 'admin'].includes(authResult.user.role)) {
    return createResponse(
      false,
      'Clinician access required',
      null,
      403
    );
  }
  
  return authResult;
}

/**
 * Optional authentication middleware
 * Returns user if authenticated, or continues without error if not
 */
export async function optionalAuth(request, env) {
  const authResult = await authenticateUser(request, env);
  
  if (authResult.success) {
    return authResult;
  }
  
  return {
    success: true,
    user: null,
    session: null
  };
}

/**
 * Refresh user session expiration
 */
export async function refreshSession(userId, sessionId, env) {
  try {
    const sessionKey = `session:${userId}`;
    const sessionData = await env.SESSIONS.get(sessionKey);
    
    if (!sessionData) {
      return false;
    }
    
    const session = JSON.parse(sessionData);
    
    // Extend session by 24 hours
    session.expires = Date.now() + (24 * 60 * 60 * 1000);
    session.lastActivity = Date.now();
    
    await env.SESSIONS.put(sessionKey, JSON.stringify(session), {
      expirationTtl: 24 * 60 * 60 // 24 hours
    });
    
    return true;
  } catch (error) {
    console.error('Session refresh error:', error);
    return false;
  }
}

/**
 * Generic role-based access control middleware
 * Returns authenticated user if they have the required role, or error response
 */
export async function requireRole(roles, request, env) {
  const authResult = await authenticateUser(request, env);
  
  if (!authResult.success) {
    return createResponse(
      false,
      authResult.error,
      null,
      authResult.statusCode
    );
  }
  
  // Convert single role to array for consistency
  const requiredRoles = Array.isArray(roles) ? roles : [roles];
  
  if (!requiredRoles.includes(authResult.user.role)) {
    return createResponse(
      false,
      `Access denied. Required role(s): ${requiredRoles.join(', ')}`,
      null,
      403
    );
  }
  
  return authResult;
}

/**
 * Hash a password using Web Crypto API (Cloudflare Workers compatible)
 * @param {string} password - Plain text password
 * @returns {Promise<string>} - Hashed password
 */
export async function hashPassword(password) {
  const encoder = new TextEncoder();
  const data = encoder.encode(password);
  const salt = crypto.getRandomValues(new Uint8Array(16));
  
  // Use PBKDF2 for password hashing
  const key = await crypto.subtle.importKey(
    'raw',
    data,
    { name: 'PBKDF2' },
    false,
    ['deriveBits']
  );
  
  const derivedBits = await crypto.subtle.deriveBits(
    {
      name: 'PBKDF2',
      salt: salt,
      iterations: 100000,
      hash: 'SHA-256'
    },
    key,
    256
  );
  
  // Combine salt and hash
  const hashArray = new Uint8Array(derivedBits);
  const combined = new Uint8Array(salt.length + hashArray.length);
  combined.set(salt);
  combined.set(hashArray, salt.length);
  
  return btoa(String.fromCharCode(...combined));
}

/**
 * Verify a password against its hash
 * @param {string} password - Plain text password
 * @param {string} hash - Hashed password
 * @returns {Promise<boolean>} - Whether password is valid
 */
export async function verifyPassword(password, hash) {
  try {
    const combined = new Uint8Array(atob(hash).split('').map(c => c.charCodeAt(0)));
    const salt = combined.slice(0, 16);
    const storedHash = combined.slice(16);
    
    const encoder = new TextEncoder();
    const data = encoder.encode(password);
    
    const key = await crypto.subtle.importKey(
      'raw',
      data,
      { name: 'PBKDF2' },
      false,
      ['deriveBits']
    );
    
    const derivedBits = await crypto.subtle.deriveBits(
      {
        name: 'PBKDF2',
        salt: salt,
        iterations: 100000,
        hash: 'SHA-256'
      },
      key,
      256
    );
    
    const computedHash = new Uint8Array(derivedBits);
    
    // Compare hashes
    if (computedHash.length !== storedHash.length) return false;
    for (let i = 0; i < computedHash.length; i++) {
      if (computedHash[i] !== storedHash[i]) return false;
    }
    return true;
  } catch (error) {
    return false;
  }
}

/**
 * Generate a JWT token for a user using Web Crypto API
 * @param {Object} user - User object
 * @param {string} jwtSecret - JWT secret key
 * @returns {Promise<string>} - JWT token
 */
export async function generateToken(user, jwtSecret) {
  const header = {
    alg: 'HS256',
    typ: 'JWT'
  };
  
  const payload = {
    id: user.id,
    email: user.email,
    role: user.role,
    exp: Math.floor(Date.now() / 1000) + (24 * 60 * 60) // 24 hours
  };
  
  const encodedHeader = btoa(JSON.stringify(header)).replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
  const encodedPayload = btoa(JSON.stringify(payload)).replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
  
  const message = encodedHeader + '.' + encodedPayload;
  const encoder = new TextEncoder();
  const key = await crypto.subtle.importKey(
    'raw',
    encoder.encode(jwtSecret),
    { name: 'HMAC', hash: 'SHA-256' },
    false,
    ['sign']
  );
  
  const signature = await crypto.subtle.sign('HMAC', key, encoder.encode(message));
  const encodedSignature = btoa(String.fromCharCode(...new Uint8Array(signature)))
    .replace(/=/g, '').replace(/\+/g, '-').replace(/\//g, '_');
  
  return message + '.' + encodedSignature;
}

// Alias for compatibility
export const generateJWT = generateToken;

/**
 * Verify and decode a JWT token using Web Crypto API
 * @param {string} token - JWT token
 * @param {string} jwtSecret - JWT secret key
 * @returns {Promise<Object|null>} - Decoded token payload or null if invalid
 */
export async function verifyToken(token, jwtSecret) {
  try {
    const parts = token.split('.');
    if (parts.length !== 3) return null;
    
    const [encodedHeader, encodedPayload, encodedSignature] = parts;
    const message = encodedHeader + '.' + encodedPayload;
    
    // Verify signature
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(jwtSecret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['verify']
    );
    
    const signature = new Uint8Array(
      atob(encodedSignature.replace(/-/g, '+').replace(/_/g, '/'))
        .split('').map(c => c.charCodeAt(0))
    );
    
    const isValid = await crypto.subtle.verify(
      'HMAC',
      key,
      signature,
      encoder.encode(message)
    );
    
    if (!isValid) return null;
    
    // Decode payload
    const payload = JSON.parse(atob(encodedPayload.replace(/-/g, '+').replace(/_/g, '/')));
    
    // Check expiration
    if (payload.exp && payload.exp < Math.floor(Date.now() / 1000)) {
      return null;
    }
    
    return payload;
  } catch (error) {
    return null;
  }
}

