                } catch (err) {
                    console.error('Error generating summary:', err);
                    error = err.message;
                } finally {
                    isGenerating = false;
                    updateUI();
                }
            }
            
            // Toggle collapse function
            function toggleCollapse() {
                isCollapsed = !isCollapsed;
                updateUI();
            }
            
