                                Cancel
                            </button>
                            <button class="btn btn-primary" data-action="save-fields">
                                Save Selection
                            </button>
                        </div>
                    </div>
                `;
                
                // Add save handler
                modal.querySelector('[data-action="save-fields"]').onclick = function() {
                    const checkboxes = modal.querySelectorAll('input[type="checkbox"]:checked');
