// Preview Modal component for form preview functionality
import notifications from '../utils/notifications.js';

export class PreviewModal {
  constructor(survey, options = {}) {
    this.survey = survey;
    this.options = {
      theme: 'modern',
      showCompleteButton: true,
      showProgressBar: true,
      fullscreen: true,
      allowEdit: false,
      ...options
    };

    this.modal = null;
    this.previewSurvey = null;
    this.isOpen = false;

    // Bind methods
    this.open = this.open.bind(this);
    this.close = this.close.bind(this);
    this.toggleFullscreen = this.toggleFullscreen.bind(this);
    this.switchDevice = this.switchDevice.bind(this);
  }

  open() {
    if (this.isOpen) {
      return;
    }

    // Create modal
    this.createModal();

    // Initialize preview survey
    this.initializePreviewSurvey();

    // Show modal
    document.body.appendChild(this.modal);
    this.modal.classList.add('show');
    this.isOpen = true;

    // Focus trap
    this.setupFocusTrap();

    // Analytics
    this.trackPreviewOpen();
  }

  close() {
    if (!this.isOpen) {
      return;
    }

    // Remove modal with animation
    this.modal.classList.remove('show');

    setTimeout(() => {
      if (this.modal && this.modal.parentNode) {
        this.modal.parentNode.removeChild(this.modal);
      }
      this.modal = null;
      this.previewSurvey = null;
      this.isOpen = false;
    }, 300);

    // Remove event listeners
    this.removeEventListeners();
  }

  createModal() {
    this.modal = document.createElement('div');
    this.modal.className = 'preview-modal';
    this.modal.innerHTML = `
      <div class="preview-modal-overlay"></div>
      <div class="preview-modal-container">
        <div class="preview-modal-header">
          <div class="preview-header-left">
            <h2><i class="fas fa-eye"></i> Form Preview</h2>
            <div class="preview-device-selector">
              <button class="device-btn active" data-device="desktop" title="Desktop">
                <i class="fas fa-desktop"></i>
              </button>
              <button class="device-btn" data-device="tablet" title="Tablet">
                <i class="fas fa-tablet-alt"></i>
              </button>
              <button class="device-btn" data-device="mobile" title="Mobile">
                <i class="fas fa-mobile-alt"></i>
              </button>
            </div>
          </div>
          <div class="preview-header-right">
            <button class="preview-theme-btn" title="Toggle Theme">
              <i class="fas fa-palette"></i>
            </button>
            <button class="preview-fullscreen-btn" title="Toggle Fullscreen">
              <i class="fas fa-expand"></i>
            </button>
            <button class="preview-close-btn" title="Close">
              <i class="fas fa-times"></i>
            </button>
          </div>
        </div>
        <div class="preview-modal-body">
          <div class="preview-device-frame desktop">
            <div class="preview-device-screen">
              <div class="preview-survey-container" id="preview-survey"></div>
            </div>
          </div>
        </div>
        <div class="preview-modal-footer">
          <div class="preview-info">
            <span class="preview-page-info"></span>
            <span class="preview-progress-info"></span>
          </div>
          <div class="preview-actions">
            <button class="btn secondary share-btn">
              <i class="fas fa-share"></i> Share Preview
            </button>
            <button class="btn secondary test-data-btn">
              <i class="fas fa-database"></i> Load Test Data
            </button>
            <button class="btn primary close-preview-btn">Close Preview</button>
          </div>
        </div>
      </div>
    `;

    // Setup event listeners
    this.setupEventListeners();
  }

  setupEventListeners() {
    // Close buttons
    this.modal.querySelector('.preview-close-btn').addEventListener('click', this.close);
    this.modal.querySelector('.close-preview-btn').addEventListener('click', this.close);
    this.modal.querySelector('.preview-modal-overlay').addEventListener('click', this.close);

    // Device selector
    this.modal.querySelectorAll('.device-btn').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const device = e.currentTarget.dataset.device;
        this.switchDevice(device);
      });
    });

    // Theme toggle
    this.modal.querySelector('.preview-theme-btn').addEventListener('click', () => {
      this.toggleTheme();
    });

    // Fullscreen toggle
    this.modal.querySelector('.preview-fullscreen-btn').addEventListener('click', () => {
      this.toggleFullscreen();
    });

    // Share button
    this.modal.querySelector('.share-btn').addEventListener('click', () => {
      this.sharePreview();
    });

    // Test data button
    this.modal.querySelector('.test-data-btn').addEventListener('click', () => {
      this.loadTestData();
    });

    // Keyboard shortcuts
    this.handleKeyboard = (e) => {
      if (e.key === 'Escape') {
        this.close();
      } else if (e.key === 'F11') {
        e.preventDefault();
        this.toggleFullscreen();
      }
    };

    document.addEventListener('keydown', this.handleKeyboard);
  }

  removeEventListeners() {
    document.removeEventListener('keydown', this.handleKeyboard);
  }

  initializePreviewSurvey() {
    // Clone survey JSON
    const surveyJSON = this.survey.toJSON();

    // Create preview survey instance
    this.previewSurvey = new Survey.Model(surveyJSON);

    // Configure preview settings
    this.configurePreviewSurvey();

    // Render survey
    const container = this.modal.querySelector('#preview-survey');
    this.previewSurvey.render(container);

    // Setup preview event handlers
    this.setupPreviewHandlers();

    // Update info
    this.updatePreviewInfo();
  }

  configurePreviewSurvey() {
    // Set preview mode
    this.previewSurvey.mode = 'display';

    // Configure appearance
    this.previewSurvey.showNavigationButtons = this.options.showNavigationButtons !== false;
    this.previewSurvey.showProgressBar = this.options.showProgressBar ? 'top' : 'off';
    this.previewSurvey.showCompletedPage = this.options.showCompleteButton;

    // Set theme
    this.previewSurvey.applyTheme(this.options.theme);

    // Disable design mode features
    this.previewSurvey.allowCompleteSurveyAutomatic = false;
    this.previewSurvey.sendResultOnPageNext = false;

    // Configure validation
    this.previewSurvey.checkErrorsMode = 'onValueChanged';
    this.previewSurvey.textUpdateMode = 'onTyping';
  }

  setupPreviewHandlers() {
    // Page changed
    this.previewSurvey.onCurrentPageChanged.add(() => {
      this.updatePreviewInfo();
      this.scrollToTop();
    });

    // Value changed
    this.previewSurvey.onValueChanged.add((sender, options) => {
      // Track interactions
      this.trackInteraction('value_changed', {
        question: options.name,
        value: options.value
      });
    });

    // Complete
    this.previewSurvey.onComplete.add(() => {
      this.handlePreviewComplete();
    });

    // Validation error
    this.previewSurvey.onValidationError.add((sender, options) => {
      this.trackInteraction('validation_error', {
        question: options.name,
        errors: options.errors
      });
    });
  }

  switchDevice(device) {
    // Update active button
    this.modal.querySelectorAll('.device-btn').forEach((btn) => {
      btn.classList.toggle('active', btn.dataset.device === device);
    });

    // Update frame class
    const frame = this.modal.querySelector('.preview-device-frame');
    frame.className = `preview-device-frame ${device}`;

    // Track device switch
    this.trackInteraction('device_switch', { device });

    // Update preview info
    this.updateDeviceInfo(device);
  }

  toggleTheme() {
    const themes = ['modern', 'default', 'bootstrap', 'winterstone', 'orange'];
    const currentTheme = this.previewSurvey.theme || 'modern';
    const currentIndex = themes.indexOf(currentTheme);
    const nextTheme = themes[(currentIndex + 1) % themes.length];

    // Apply new theme
    this.previewSurvey.applyTheme(nextTheme);

    // Show notification
    notifications.info(`Theme changed to: ${nextTheme}`);

    // Track theme change
    this.trackInteraction('theme_change', { theme: nextTheme });
  }

  toggleFullscreen() {
    const container = this.modal.querySelector('.preview-modal-container');
    const isFullscreen = container.classList.contains('fullscreen');

    container.classList.toggle('fullscreen');

    // Update icon
    const icon = this.modal.querySelector('.preview-fullscreen-btn i');
    icon.className = isFullscreen ? 'fas fa-expand' : 'fas fa-compress';

    // Track fullscreen toggle
    this.trackInteraction('fullscreen_toggle', { fullscreen: !isFullscreen });
  }

  sharePreview() {
    // Generate shareable link
    const shareData = {
      surveyId: this.survey.surveyId || 'preview',
      timestamp: Date.now(),
      expiresIn: 24 * 60 * 60 * 1000 // 24 hours
    };

    // Create share modal
    const shareModal = document.createElement('div');
    shareModal.className = 'share-modal';
    shareModal.innerHTML = `
      <div class="share-modal-content">
        <h3>Share Preview Link</h3>
        <p>This preview link will expire in 24 hours</p>
        <div class="share-link-container">
          <input type="text" class="share-link-input" value="${this.generateShareLink(shareData)}" readonly>
          <button class="copy-link-btn" title="Copy link">
            <i class="fas fa-copy"></i>
          </button>
        </div>
        <div class="share-options">
          <button class="share-option-btn" data-method="email">
            <i class="fas fa-envelope"></i> Email
          </button>
          <button class="share-option-btn" data-method="qr">
            <i class="fas fa-qrcode"></i> QR Code
          </button>
        </div>
        <button class="btn primary close-share-btn">Done</button>
      </div>
    `;

    // Add to modal
    this.modal.appendChild(shareModal);

    // Setup share modal events
    this.setupShareModalEvents(shareModal);

    // Show with animation
    setTimeout(() => shareModal.classList.add('show'), 10);
  }

  setupShareModalEvents(shareModal) {
    // Copy link
    const copyBtn = shareModal.querySelector('.copy-link-btn');
    const input = shareModal.querySelector('.share-link-input');

    copyBtn.addEventListener('click', () => {
      input.select();
      document.execCommand('copy');

      // Show feedback
      copyBtn.innerHTML = '<i class="fas fa-check"></i>';
      setTimeout(() => {
        copyBtn.innerHTML = '<i class="fas fa-copy"></i>';
      }, 2000);

      notifications.success('Link copied to clipboard!');
    });

    // Share options
    shareModal.querySelectorAll('.share-option-btn').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const method = e.currentTarget.dataset.method;
        this.handleShareMethod(method, input.value);
      });
    });

    // Close
    shareModal.querySelector('.close-share-btn').addEventListener('click', () => {
      shareModal.classList.remove('show');
      setTimeout(() => shareModal.remove(), 300);
    });
  }

  generateShareLink(data) {
    // In production, this would generate a real shareable link
    const baseUrl = window.location.origin;
    const params = new URLSearchParams({
      preview: data.surveyId,
      token: btoa(JSON.stringify(data)),
      t: data.timestamp
    });

    return `${baseUrl}/preview?${params.toString()}`;
  }

  handleShareMethod(method, link) {
    switch (method) {
      case 'email':
        const subject = encodeURIComponent(`Preview: ${this.survey.title || 'Form'}`);
        const body = encodeURIComponent(`Click here to preview the form:\n\n${link}`);
        window.open(`mailto:?subject=${subject}&body=${body}`);
        break;

      case 'qr':
        this.showQRCode(link);
        break;
    }
  }

  showQRCode(link) {
    // Create QR code modal
    const qrModal = document.createElement('div');
    qrModal.className = 'qr-modal';
    qrModal.innerHTML = `
      <div class="qr-modal-content">
        <h3>QR Code</h3>
        <div class="qr-code-container" id="qr-code"></div>
        <p>Scan this code to preview on mobile</p>
        <button class="btn primary">Close</button>
      </div>
    `;

    this.modal.appendChild(qrModal);

    // Generate QR code (requires qrcode.js library)
    if (window.QRCode) {
      new QRCode(qrModal.querySelector('#qr-code'), {
        text: link,
        width: 200,
        height: 200
      });
    } else {
      // Fallback - show link
      qrModal.querySelector('#qr-code').innerHTML = `
        <p style="padding: 20px; text-align: center; color: #666;">
          QR Code library not loaded
        </p>
      `;
    }

    // Close button
    qrModal.querySelector('button').addEventListener('click', () => {
      qrModal.remove();
    });

    // Show with animation
    setTimeout(() => qrModal.classList.add('show'), 10);
  }

  loadTestData() {
    // Generate test data based on question types
    const testData = this.generateTestData();

    // Apply test data
    Object.keys(testData).forEach((key) => {
      this.previewSurvey.setValue(key, testData[key]);
    });

    notifications.success('Test data loaded');

    // Track test data load
    this.trackInteraction('test_data_loaded');
  }

  generateTestData() {
    const testData = {};

    this.previewSurvey.getAllQuestions().forEach((question) => {
      const name = question.name;
      const type = question.getType();

      switch (type) {
        case 'text':
          testData[name] = this.generateTextData(question);
          break;

        case 'comment':
          testData[name] =
            'This is a sample comment for testing purposes. It contains multiple sentences to show how longer text appears.';
          break;

        case 'radiogroup':
        case 'dropdown':
          if (question.choices && question.choices.length > 0) {
            const randomIndex = Math.floor(Math.random() * question.choices.length);
            testData[name] = question.choices[randomIndex].value || question.choices[randomIndex];
          }
          break;

        case 'checkbox':
          if (question.choices && question.choices.length > 0) {
            const selectedCount = Math.min(
              2,
              Math.floor(Math.random() * question.choices.length) + 1
            );
            const selected = [];
            for (let i = 0; i < selectedCount; i++) {
              const choice = question.choices[i];
              selected.push(choice.value || choice);
            }
            testData[name] = selected;
          }
          break;

        case 'boolean':
          testData[name] = Math.random() > 0.5;
          break;

        case 'rating':
          const min = question.rateMin || 1;
          const max = question.rateMax || 5;
          testData[name] = Math.floor(Math.random() * (max - min + 1)) + min;
          break;

        case 'matrix':
          const matrixData = {};
          if (question.rows) {
            question.rows.forEach((row) => {
              const rowValue = row.value || row;
              if (question.columns && question.columns.length > 0) {
                const randomCol =
                  question.columns[Math.floor(Math.random() * question.columns.length)];
                matrixData[rowValue] = randomCol.value || randomCol;
              }
            });
          }
          testData[name] = matrixData;
          break;

        case 'file':
          // Skip file questions
          break;

        case 'signaturepad':
          // Skip signature questions
          break;

        default:
          // For other types, try to set a generic value
          testData[name] = `Test value for ${type}`;
      }
    });

    return testData;
  }

  generateTextData(question) {
    const inputType = question.inputType || 'text';

    switch (inputType) {
      case 'email':
        return 'test@example.com';
      case 'tel':
        return '(555) 123-4567';
      case 'number':
        return Math.floor(Math.random() * 100).toString();
      case 'date':
        return new Date().toISOString().split('T')[0];
      case 'time':
        return '14:30';
      case 'url':
        return 'https://example.com';
      default:
        return 'Sample text response';
    }
  }

  handlePreviewComplete() {
    // Show completion screen
    const container = this.modal.querySelector('#preview-survey');
    container.innerHTML = `
      <div class="preview-complete">
        <i class="fas fa-check-circle"></i>
        <h2>Form Completed!</h2>
        <p>This is what users will see after submitting the form.</p>
        <div class="preview-complete-actions">
          <button class="btn secondary restart-preview">
            <i class="fas fa-redo"></i> Restart Preview
          </button>
          <button class="btn primary view-results">
            <i class="fas fa-chart-bar"></i> View Results
          </button>
        </div>
      </div>
    `;

    // Setup complete screen events
    container.querySelector('.restart-preview').addEventListener('click', () => {
      this.restartPreview();
    });

    container.querySelector('.view-results').addEventListener('click', () => {
      this.showPreviewResults();
    });

    // Track completion
    this.trackInteraction('preview_completed');
  }

  restartPreview() {
    // Reinitialize preview survey
    this.initializePreviewSurvey();
  }

  showPreviewResults() {
    const data = this.previewSurvey.data;

    // Create results modal
    const resultsModal = document.createElement('div');
    resultsModal.className = 'results-modal';
    resultsModal.innerHTML = `
      <div class="results-modal-content">
        <h3>Preview Results</h3>
        <div class="results-data">
          <pre>${JSON.stringify(data, null, 2)}</pre>
        </div>
        <div class="results-actions">
          <button class="btn secondary copy-results">
            <i class="fas fa-copy"></i> Copy JSON
          </button>
          <button class="btn primary close-results">Close</button>
        </div>
      </div>
    `;

    this.modal.appendChild(resultsModal);

    // Setup events
    resultsModal.querySelector('.copy-results').addEventListener('click', () => {
      const textArea = document.createElement('textarea');
      textArea.value = JSON.stringify(data, null, 2);
      document.body.appendChild(textArea);
      textArea.select();
      document.execCommand('copy');
      document.body.removeChild(textArea);

      notifications.success('Results copied to clipboard');
    });

    resultsModal.querySelector('.close-results').addEventListener('click', () => {
      resultsModal.remove();
    });

    // Show with animation
    setTimeout(() => resultsModal.classList.add('show'), 10);
  }

  updatePreviewInfo() {
    // Update page info
    const pageInfo = this.modal.querySelector('.preview-page-info');
    const currentPage = this.previewSurvey.currentPageNo + 1;
    const totalPages = this.previewSurvey.visiblePageCount;
    pageInfo.textContent = `Page ${currentPage} of ${totalPages}`;

    // Update progress info
    const progressInfo = this.modal.querySelector('.preview-progress-info');
    const progress = Math.round(this.previewSurvey.getProgress());
    progressInfo.textContent = `${progress}% Complete`;
  }

  updateDeviceInfo(device) {
    const deviceSizes = {
      desktop: { width: '100%', info: 'Desktop View' },
      tablet: { width: '768px', info: 'Tablet View (768px)' },
      mobile: { width: '375px', info: 'Mobile View (375px)' }
    };

    const info = deviceSizes[device];
    notifications.info(info.info);
  }

  scrollToTop() {
    const screen = this.modal.querySelector('.preview-device-screen');
    screen.scrollTop = 0;
  }

  setupFocusTrap() {
    const focusableElements = this.modal.querySelectorAll(
      'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
    );

    const firstElement = focusableElements[0];
    const lastElement = focusableElements[focusableElements.length - 1];

    this.handleTab = (e) => {
      if (e.key !== 'Tab') {
        return;
      }

      if (e.shiftKey && document.activeElement === firstElement) {
        e.preventDefault();
        lastElement.focus();
      } else if (!e.shiftKey && document.activeElement === lastElement) {
        e.preventDefault();
        firstElement.focus();
      }
    };

    this.modal.addEventListener('keydown', this.handleTab);

    // Focus first element
    setTimeout(() => firstElement.focus(), 100);
  }

  trackPreviewOpen() {
    // Analytics tracking
    if (window.gtag) {
      window.gtag('event', 'preview_open', {
        survey_id: this.survey.surveyId,
        question_count: this.survey.getAllQuestions().length,
        page_count: this.survey.pages.length
      });
    }
  }

  trackInteraction(action, data = {}) {
    // Analytics tracking
    if (window.gtag) {
      window.gtag('event', `preview_${action}`, {
        survey_id: this.survey.surveyId,
        ...data
      });
    }
  }

  // Public API
  isVisible() {
    return this.isOpen;
  }

  refresh() {
    if (this.isOpen && this.previewSurvey) {
      // Update survey JSON
      const surveyJSON = this.survey.toJSON();
      this.previewSurvey.fromJSON(surveyJSON);

      // Update info
      this.updatePreviewInfo();
    }
  }

  destroy() {
    this.close();
    this.survey = null;
    this.options = null;
  }
}

// Factory function
export function createPreviewModal(survey, options) {
  return new PreviewModal(survey, options);
}

// Export default options
export const PREVIEW_MODAL_OPTIONS = {
  theme: 'modern',
  showCompleteButton: true,
  showProgressBar: true,
  showNavigationButtons: true,
  fullscreen: true,
  allowEdit: false,
  devices: ['desktop', 'tablet', 'mobile'],
  themes: ['modern', 'default', 'bootstrap', 'winterstone', 'orange'],
  testDataEnabled: true,
  shareEnabled: true,
  analyticsEnabled: true
};

// AI Helper component for generating and improving form questions
import notifications from '../utils/notifications.js';
import { debounce } from '../utils/debounce.js';

// AI Helper class
export class AIHelper {
  constructor(survey, apiConfig = {}) {
    this.survey = survey;
    this.apiConfig = {
      endpoint: '/api/ai/chat',
      summaryEndpoint: '/api/ai/summary',
      maxRetries: 3,
      timeout: 30000,
      ...apiConfig
    };

    this.isProcessing = false;
    this.currentRequest = null;
    this.suggestions = new Map();

    // Initialize UI
    this.initializeUI();

    // Bind methods
    this.generateQuestion = this.generateQuestion.bind(this);
    this.improveQuestion = this.improveQuestion.bind(this);
    this.suggestOptions = this.suggestOptions.bind(this);
    this.analyzeSurvey = this.analyzeSurvey.bind(this);
  }

  initializeUI() {
    // Create AI helper panel
    this.panel = document.createElement('div');
    this.panel.className = 'ai-helper-panel';
    this.panel.innerHTML = `
      <div class="ai-helper-header">
        <h3><i class="fas fa-robot"></i> AI Assistant</h3>
        <button class="ai-helper-close" title="Close">
          <i class="fas fa-times"></i>
        </button>
      </div>
      <div class="ai-helper-content">
        <div class="ai-helper-prompt">
          <textarea 
            id="ai-prompt" 
            placeholder="Describe what kind of question you want to create..."
            rows="3"
          ></textarea>
          <div class="ai-helper-actions">
            <button class="ai-action-btn primary" data-action="generate">
              <i class="fas fa-magic"></i> Generate Question
            </button>
            <button class="ai-action-btn" data-action="improve">
              <i class="fas fa-sparkles"></i> Improve Current
            </button>
            <button class="ai-action-btn" data-action="suggest">
              <i class="fas fa-lightbulb"></i> Suggest Options
            </button>
          </div>
        </div>
        <div class="ai-helper-suggestions" style="display: none;">
          <h4>Suggestions</h4>
          <div class="suggestions-list"></div>
        </div>
        <div class="ai-helper-loading" style="display: none;">
          <div class="spinner"></div>
          <p>AI is thinking...</p>
        </div>
        <div class="ai-helper-error" style="display: none;">
          <i class="fas fa-exclamation-triangle"></i>
          <p class="error-message"></p>
          <button class="retry-btn">Retry</button>
        </div>
      </div>
      <div class="ai-helper-footer">
        <button class="ai-analyze-btn" data-action="analyze">
          <i class="fas fa-chart-line"></i> Analyze Survey
        </button>
        <div class="ai-helper-tips">
          <i class="fas fa-info-circle"></i>
          <span>Tip: Be specific about your requirements for better results</span>
        </div>
      </div>
    `;

    // Add event listeners
    this.setupEventListeners();

    // Create floating button
    this.createFloatingButton();
  }

  setupEventListeners() {
    // Close button
    this.panel.querySelector('.ai-helper-close').addEventListener('click', () => {
      this.hide();
    });

    // Action buttons
    this.panel.querySelectorAll('.ai-action-btn').forEach((btn) => {
      btn.addEventListener('click', (e) => {
        const action = e.currentTarget.dataset.action;
        this.handleAction(action);
      });
    });

    // Analyze button
    this.panel.querySelector('.ai-analyze-btn').addEventListener('click', () => {
      this.handleAction('analyze');
    });

    // Retry button
    this.panel.querySelector('.retry-btn').addEventListener('click', () => {
      this.retry();
    });

    // Prompt textarea - auto-resize
    const promptTextarea = this.panel.querySelector('#ai-prompt');
    promptTextarea.addEventListener('input', () => {
      promptTextarea.style.height = 'auto';
      promptTextarea.style.height = `${promptTextarea.scrollHeight  }px`;
    });

    // Debounced suggestion updates
    this.updateSuggestions = debounce(() => {
      if (this.getCurrentQuestion()) {
        this.getSuggestions();
      }
    }, 1000);
  }

  createFloatingButton() {
    this.floatingBtn = document.createElement('button');
    this.floatingBtn.className = 'ai-helper-floating-btn';
    this.floatingBtn.innerHTML = '<i class="fas fa-robot"></i>';
    this.floatingBtn.title = 'Open AI Assistant';

    this.floatingBtn.addEventListener('click', () => {
      this.show();
    });

    document.body.appendChild(this.floatingBtn);
  }

  show() {
    if (!document.body.contains(this.panel)) {
      document.body.appendChild(this.panel);
    }

    this.panel.classList.add('show');
    this.floatingBtn.classList.add('hidden');

    // Focus on prompt
    setTimeout(() => {
      this.panel.querySelector('#ai-prompt').focus();
    }, 300);

    // Update context
    this.updateContext();
  }

  hide() {
    this.panel.classList.remove('show');
    this.floatingBtn.classList.remove('hidden');

    // Clear any ongoing requests
    if (this.currentRequest) {
      this.currentRequest.abort();
      this.currentRequest = null;
    }

    // Reset UI
    this.resetUI();
  }

  updateContext() {
    const currentQuestion = this.getCurrentQuestion();
    if (currentQuestion) {
      // Update UI based on current question
      const prompt = this.panel.querySelector('#ai-prompt');
      prompt.placeholder = `Improve "${currentQuestion.title}" or describe a new question...`;

      // Enable/disable buttons
      this.panel.querySelector('[data-action="improve"]').disabled = false;
      this.panel.querySelector('[data-action="suggest"]').disabled = ![
        'dropdown',
        'radiogroup',
        'checkbox'
      ].includes(currentQuestion.getType());
    } else {
      // Reset to default state
      this.panel.querySelector('[data-action="improve"]').disabled = true;
      this.panel.querySelector('[data-action="suggest"]').disabled = true;
    }
  }

  getCurrentQuestion() {
    // Get currently selected question in the designer
    return this.survey.currentQuestion || this.survey.selectedElement;
  }

  handleAction(action) {
    const prompt = this.panel.querySelector('#ai-prompt').value.trim();

    switch (action) {
      case 'generate':
        if (!prompt) {
          notifications.warning('Please describe the question you want to create');
          return;
        }
        this.generateQuestion(prompt);
        break;

      case 'improve':
        this.improveQuestion(prompt);
        break;

      case 'suggest':
        this.suggestOptions(prompt);
        break;

      case 'analyze':
        this.analyzeSurvey();
        break;
    }
  }

  async generateQuestion(prompt) {
    if (this.isProcessing) {return;}

    this.showLoading();

    try {
      const context = this.getContextData();
      const response = await this.callAI({
        action: 'generate_question',
        prompt,
        context,
        surveyTitle: this.survey.title,
        existingQuestions: this.getExistingQuestions()
      });

      if (response.success && response.question) {
        // Add the generated question to the survey
        this.addQuestionToSurvey(response.question);

        notifications.success('Question generated successfully!');

        // Show suggestions if any
        if (response.suggestions) {
          this.showSuggestions(response.suggestions);
        }

        // Clear prompt
        this.panel.querySelector('#ai-prompt').value = '';
      } else {
        throw new Error(response.error || 'Failed to generate question');
      }
    } catch (error) {
      this.showError(error.message);
    } finally {
      this.hideLoading();
    }
  }

  async improveQuestion(additionalPrompt = '') {
    const currentQuestion = this.getCurrentQuestion();
    if (!currentQuestion) {
      notifications.warning('Please select a question to improve');
      return;
    }

    if (this.isProcessing) {return;}

    this.showLoading();

    try {
      const response = await this.callAI({
        action: 'improve_question',
        question: this.serializeQuestion(currentQuestion),
        additionalPrompt,
        context: this.getContextData(),
        surveyTitle: this.survey.title
      });

      if (response.success && response.improvements) {
        // Apply improvements
        this.applyImprovements(currentQuestion, response.improvements);

        notifications.success('Question improved successfully!');

        // Show suggestions
        if (response.suggestions) {
          this.showSuggestions(response.suggestions);
        }
      } else {
        throw new Error(response.error || 'Failed to improve question');
      }
    } catch (error) {
      this.showError(error.message);
    } finally {
      this.hideLoading();
    }
  }

  async suggestOptions(additionalPrompt = '') {
    const currentQuestion = this.getCurrentQuestion();
    if (!currentQuestion) {
      notifications.warning('Please select a question to get suggestions');
      return;
    }

    const questionType = currentQuestion.getType();
    if (!['dropdown', 'radiogroup', 'checkbox'].includes(questionType)) {
      notifications.info('Option suggestions are only available for choice questions');
      return;
    }

    if (this.isProcessing) {return;}

    this.showLoading();

    try {
      const response = await this.callAI({
        action: 'suggest_options',
        question: this.serializeQuestion(currentQuestion),
        additionalPrompt,
        context: this.getContextData(),
        surveyTitle: this.survey.title
      });

      if (response.success && response.options) {
        // Show options for user to select
        this.showOptionSuggestions(currentQuestion, response.options);
      } else {
        throw new Error(response.error || 'Failed to generate suggestions');
      }
    } catch (error) {
      this.showError(error.message);
    } finally {
      this.hideLoading();
    }
  }

  async analyzeSurvey() {
    if (this.isProcessing) {return;}

    this.showLoading('Analyzing survey structure...');

    try {
      const response = await this.callAI(
        {
          action: 'analyze_survey',
          survey: this.serializeSurvey(),
          requestAnalysis: {
            structure: true,
            completeness: true,
            accessibility: true,
            suggestions: true
          }
        },
        this.apiConfig.summaryEndpoint
      );

      if (response.success && response.analysis) {
        // Show analysis results
        this.showAnalysisResults(response.analysis);
      } else {
        throw new Error(response.error || 'Failed to analyze survey');
      }
    } catch (error) {
      this.showError(error.message);
    } finally {
      this.hideLoading();
    }
  }

  async callAI(data, endpoint = null) {
    const controller = new AbortController();
    this.currentRequest = controller;

    try {
      const response = await fetch(endpoint || this.apiConfig.endpoint, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json'
        },
        body: JSON.stringify(data),
        signal: controller.signal,
        timeout: this.apiConfig.timeout
      });

      if (!response.ok) {
        throw new Error(`API error: ${response.status} ${response.statusText}`);
      }

      const result = await response.json();
      return result;
    } catch (error) {
      if (error.name === 'AbortError') {
        throw new Error('Request cancelled');
      }
      throw error;
    } finally {
      this.currentRequest = null;
    }
  }

  addQuestionToSurvey(questionData) {
    // Create new question
    const question = this.survey.currentPage.addNewQuestion(
      questionData.type || 'text',
      questionData.name || this.generateQuestionName()
    );

    // Apply properties
    Object.keys(questionData).forEach((key) => {
      if (key !== 'type' && key !== 'name') {
        question[key] = questionData[key];
      }
    });

    // Mark as AI generated
    question.aiGenerated = true;

    // Select the new question
    this.survey.selectedElement = question;

    // Trigger update
    this.survey.onPropertyValueChangedCallback(questionData.name, questionData, null, null);
  }

  applyImprovements(question, improvements) {
    // Apply each improvement
    Object.keys(improvements).forEach((key) => {
      if (question[key] !== undefined) {
        const oldValue = question[key];
        question[key] = improvements[key];

        // Trigger property change
        this.survey.onPropertyValueChangedCallback(key, improvements[key], oldValue, question);
      }
    });

    // Mark as AI improved
    question.aiGenerated = true;
  }

  showSuggestions(suggestions) {
    const suggestionsDiv = this.panel.querySelector('.ai-helper-suggestions');
    const suggestionsList = suggestionsDiv.querySelector('.suggestions-list');

    // Clear previous suggestions
    suggestionsList.innerHTML = '';

    // Add new suggestions
    suggestions.forEach((suggestion) => {
      const item = document.createElement('div');
      item.className = 'suggestion-item';
      item.innerHTML = `
        <div class="suggestion-content">
          <h5>${suggestion.title}</h5>
          <p>${suggestion.description}</p>
        </div>
        <button class="apply-suggestion-btn" title="Apply">
          <i class="fas fa-check"></i>
        </button>
      `;

      // Apply suggestion on click
      item.querySelector('.apply-suggestion-btn').addEventListener('click', () => {
        this.applySuggestion(suggestion);
      });

      suggestionsList.appendChild(item);
    });

    // Show suggestions panel
    suggestionsDiv.style.display = 'block';
  }

  showOptionSuggestions(question, options) {
    const suggestionsDiv = this.panel.querySelector('.ai-helper-suggestions');
    const suggestionsList = suggestionsDiv.querySelector('.suggestions-list');

    // Clear previous suggestions
    suggestionsList.innerHTML = '';

    // Create options selector
    const selector = document.createElement('div');
    selector.className = 'options-selector';
    selector.innerHTML = `
      <h4>Select options to add:</h4>
      <div class="options-list">
        ${options
          .map(
            (option, index) => `
          <label class="option-item">
            <input type="checkbox" value="${index}" checked>
            <span>${option.text}</span>
          </label>
        `
          )
          .join('')}
      </div>
      <div class="options-actions">
        <button class="btn primary apply-options">Apply Selected</button>
        <button class="btn cancel-options">Cancel</button>
      </div>
    `;

    // Handle apply
    selector.querySelector('.apply-options').addEventListener('click', () => {
      const selected = Array.from(selector.querySelectorAll('input:checked')).map(
        (input) => options[parseInt(input.value)]
      );

      if (selected.length > 0) {
        // Apply selected options
        question.choices = [...(question.choices || []), ...selected];
        notifications.success(`Added ${selected.length} options`);

        // Hide suggestions
        suggestionsDiv.style.display = 'none';
      }
    });

    // Handle cancel
    selector.querySelector('.cancel-options').addEventListener('click', () => {
      suggestionsDiv.style.display = 'none';
    });

    suggestionsList.appendChild(selector);
    suggestionsDiv.style.display = 'block';
  }

  showAnalysisResults(analysis) {
    // Create analysis modal
    const modal = document.createElement('div');
    modal.className = 'ai-analysis-modal';
    modal.innerHTML = `
      <div class="ai-analysis-content">
        <div class="ai-analysis-header">
          <h2>Survey Analysis Results</h2>
          <button class="close-btn"><i class="fas fa-times"></i></button>
        </div>
        <div class="ai-analysis-body">
          ${this.renderAnalysisContent(analysis)}
        </div>
        <div class="ai-analysis-footer">
          <button class="btn primary">Close</button>
        </div>
      </div>
    `;

    // Add event listeners
    modal.querySelector('.close-btn').addEventListener('click', () => {
      modal.remove();
    });

    modal.querySelector('.btn.primary').addEventListener('click', () => {
      modal.remove();
    });

    // Add to body
    document.body.appendChild(modal);

    // Show with animation
    setTimeout(() => modal.classList.add('show'), 10);
  }

  renderAnalysisContent(analysis) {
    let html = '<div class="analysis-sections">';

    // Structure analysis
    if (analysis.structure) {
      html += `
        <div class="analysis-section">
          <h3><i class="fas fa-sitemap"></i> Structure</h3>
          <div class="analysis-metrics">
            <div class="metric">
              <span class="label">Total Questions:</span>
              <span class="value">${analysis.structure.totalQuestions}</span>
            </div>
            <div class="metric">
              <span class="label">Pages:</span>
              <span class="value">${analysis.structure.pageCount}</span>
            </div>
            <div class="metric">
              <span class="label">Question Types:</span>
              <span class="value">${analysis.structure.questionTypes.join(', ')}</span>
            </div>
          </div>
        </div>
      `;
    }

    // Completeness analysis
    if (analysis.completeness) {
      const score = analysis.completeness.score;
      const scoreClass = score >= 80 ? 'good' : score >= 60 ? 'fair' : 'poor';

      html += `
        <div class="analysis-section">
          <h3><i class="fas fa-check-circle"></i> Completeness</h3>
          <div class="completeness-score ${scoreClass}">
            <div class="score-value">${score}%</div>
            <div class="score-label">Complete</div>
          </div>
          <ul class="completeness-issues">
            ${analysis.completeness.issues
              .map((issue) => `<li><i class="fas fa-exclamation-triangle"></i> ${issue}</li>`)
              .join('')}
          </ul>
        </div>
      `;
    }

    // Accessibility analysis
    if (analysis.accessibility) {
      html += `
        <div class="analysis-section">
          <h3><i class="fas fa-universal-access"></i> Accessibility</h3>
          <ul class="accessibility-checks">
            ${analysis.accessibility.checks
              .map(
                (check) => `
              <li class="${check.passed ? 'passed' : 'failed'}">
                <i class="fas fa-${check.passed ? 'check' : 'times'}"></i>
                ${check.description}
              </li>
            `
              )
              .join('')}
          </ul>
        </div>
      `;
    }

    // Suggestions
    if (analysis.suggestions && analysis.suggestions.length > 0) {
      html += `
        <div class="analysis-section">
          <h3><i class="fas fa-lightbulb"></i> Suggestions</h3>
          <div class="suggestions-list">
            ${analysis.suggestions
              .map(
                (suggestion) => `
              <div class="suggestion-card">
                <h4>${suggestion.title}</h4>
                <p>${suggestion.description}</p>
                ${
                  suggestion.action
                    ? `
                  <button class="apply-suggestion-btn" onclick="aiHelper.applySuggestion(${JSON.stringify(suggestion).replace(/"/g, '&quot;')})">
                    Apply Suggestion
                  </button>
                `
                    : ''
                }
              </div>
            `
              )
              .join('')}
          </div>
        </div>
      `;
    }

    html += '</div>';
    return html;
  }

  applySuggestion(suggestion) {
    if (suggestion.action) {
      try {
        // Execute the suggestion action
        if (typeof suggestion.action === 'function') {
          suggestion.action(this.survey);
        } else if (suggestion.action.type === 'addQuestion') {
          this.addQuestionToSurvey(suggestion.action.question);
        } else if (suggestion.action.type === 'modifyQuestion') {
          const question = this.survey.getQuestionByName(suggestion.action.questionName);
          if (question) {
            this.applyImprovements(question, suggestion.action.changes);
          }
        }

        notifications.success('Suggestion applied successfully!');
      } catch (error) {
        notifications.error(`Failed to apply suggestion: ${  error.message}`);
      }
    }
  }

  showLoading(message = 'Processing...') {
    this.isProcessing = true;
    const loadingDiv = this.panel.querySelector('.ai-helper-loading');
    loadingDiv.querySelector('p').textContent = message;
    loadingDiv.style.display = 'block';

    // Hide other panels
    this.panel.querySelector('.ai-helper-suggestions').style.display = 'none';
    this.panel.querySelector('.ai-helper-error').style.display = 'none';

    // Disable buttons
    this.panel.querySelectorAll('button').forEach((btn) => {
      if (!btn.classList.contains('ai-helper-close')) {
        btn.disabled = true;
      }
    });
  }

  hideLoading() {
    this.isProcessing = false;
    this.panel.querySelector('.ai-helper-loading').style.display = 'none';

    // Enable buttons
    this.panel.querySelectorAll('button').forEach((btn) => {
      btn.disabled = false;
    });

    // Update context
    this.updateContext();
  }

  showError(message) {
    const errorDiv = this.panel.querySelector('.ai-helper-error');
    errorDiv.querySelector('.error-message').textContent = message;
    errorDiv.style.display = 'block';

    // Store last action for retry
    this.lastAction = this.currentAction;
  }

  retry() {
    if (this.lastAction) {
      this.handleAction(this.lastAction);
    }
  }

  resetUI() {
    this.panel.querySelector('#ai-prompt').value = '';
    this.panel.querySelector('.ai-helper-suggestions').style.display = 'none';
    this.panel.querySelector('.ai-helper-loading').style.display = 'none';
    this.panel.querySelector('.ai-helper-error').style.display = 'none';
  }

  // Helper methods
  getContextData() {
    return {
      surveyType: this.survey.surveyType || 'general',
      currentPage: this.survey.currentPage?.name,
      questionCount: this.survey.getAllQuestions().length,
      pageCount: this.survey.pages.length,
      hasConditionalLogic: this.hasConditionalLogic(),
      theme: this.survey.theme || 'default'
    };
  }

  getExistingQuestions() {
    return this.survey.getAllQuestions().map((q) => ({
      name: q.name,
      type: q.getType(),
      title: q.title
    }));
  }

  serializeQuestion(question) {
    return {
      name: question.name,
      type: question.getType(),
      title: question.title,
      description: question.description,
      isRequired: question.isRequired,
      choices: question.choices,
      hasOther: question.hasOther,
      validators: question.validators,
      visibleIf: question.visibleIf,
      enableIf: question.enableIf
    };
  }

  serializeSurvey() {
    return {
      title: this.survey.title,
      description: this.survey.description,
      pages: this.survey.pages.map((page) => ({
        name: page.name,
        title: page.title,
        questions: page.questions.map((q) => this.serializeQuestion(q))
      })),
      calculatedValues: this.survey.calculatedValues,
      triggers: this.survey.triggers
    };
  }

  hasConditionalLogic() {
    return this.survey
      .getAllQuestions()
      .some((q) => q.visibleIf || q.enableIf || q.validators?.length > 0);
  }

  generateQuestionName() {
    const timestamp = Date.now();
    const random = Math.floor(Math.random() * 1000);
    return `question_${timestamp}_${random}`;
  }

  // Public API
  destroy() {
    // Remove UI elements
    if (this.panel.parentNode) {
      this.panel.parentNode.removeChild(this.panel);
    }

    if (this.floatingBtn.parentNode) {
      this.floatingBtn.parentNode.removeChild(this.floatingBtn);
    }

    // Clear references
    this.survey = null;
    this.currentRequest = null;
    this.suggestions.clear();
  }
}

// Export singleton instance creator
export function createAIHelper(survey, config) {
  return new AIHelper(survey, config);
}

// Export default configuration
export const AI_HELPER_CONFIG = {
  endpoint: '/api/ai/chat',
  summaryEndpoint: '/api/ai/summary',
  maxRetries: 3,
  timeout: 30000,
  features: {
    generateQuestion: true,
    improveQuestion: true,
    suggestOptions: true,
    analyzeSurvey: true
  },
  prompts: {
    generateQuestion: 'Generate a survey question based on: ',
    improveQuestion: 'Improve this question: ',
    suggestOptions: 'Suggest answer options for: ',
    analyzeSurvey: 'Analyze this survey for improvements'
  }
};

export class EditDialog {
  constructor(element, options = {}) {
    this.element = element;
    this.options = options;
    this.onSave = options.onSave || (() => {});
    this.onCancel = options.onCancel || (() => {});
    this.dialog = null;
    this.form = null;
  }

  show() {
    this.createDialog();
    this.populateForm();
    document.body.appendChild(this.dialog);
    this.dialog.classList.add('active');
  }

  hide() {
    if (this.dialog) {
      this.dialog.classList.remove('active');
      setTimeout(() => {
        this.dialog.remove();
        this.dialog = null;
      }, 300);
    }
  }

  createDialog() {
    this.dialog = document.createElement('div');
    this.dialog.className = 'edit-dialog-overlay';
    this.dialog.innerHTML = `
            <div class="edit-dialog">
                <div class="edit-dialog-header">
                    <h3>Edit ${this.element.type} Question</h3>
                    <button class="close-btn">&times;</button>
                </div>
                <form class="edit-dialog-form">
                    <div class="form-section">
                        <h4>Basic Properties</h4>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: 500;">Field Name</label>
                            <input type="text" name="name" required class="form-control" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                            <small style="color: #6c757d;">Used for data storage (no spaces)</small>
                        </div>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: 500;">Display Title</label>
                            <input type="text" name="title" class="form-control" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                        </div>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: 500;">Description</label>
                            <textarea name="description" rows="2" class="form-control" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;"></textarea>
                        </div>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: flex; align-items: center;">
                                <input type="checkbox" name="isRequired" style="margin-right: 8px;">
                                Required field
                            </label>
                        </div>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: flex; align-items: center;">
                                <input type="checkbox" name="startWithNewLine" style="margin-right: 8px;">
                                Start on new line
                            </label>
                        </div>
                    </div>
                    
                    <div class="form-section">
                        <h4>Type-Specific Properties</h4>
                        ${this.getTypeSpecificFields()}
                    </div>
                    
                    <div class="form-section">
                        <h4>Advanced Properties</h4>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: 500;">Visible If</label>
                            <input type="text" name="visibleIf" class="form-control" placeholder="e.g., {question1} = 'yes'" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                            <small style="color: #6c757d;">Condition for showing this question</small>
                        </div>
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: block; margin-bottom: 5px; font-weight: 500;">Enable If</label>
                            <input type="text" name="enableIf" class="form-control" placeholder="e.g., {question2} > 5" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                            <small style="color: #6c757d;">Condition for enabling this question</small>
                        </div>
                    </div>
                    
                    <div class="form-actions">
                        <button type="submit" class="save-btn">Save Changes</button>
                        <button type="button" class="cancel-btn">Cancel</button>
                    </div>
                </form>
            </div>
        `;

    this.form = this.dialog.querySelector('.edit-dialog-form');
    this.setupEventListeners();
  }

  setupEventListeners() {
    const closeBtn = this.dialog.querySelector('.close-btn');
    const cancelBtn = this.dialog.querySelector('.cancel-btn');
    const overlay = this.dialog;

    closeBtn.addEventListener('click', () => {
      this.onCancel();
      this.hide();
    });

    cancelBtn.addEventListener('click', () => {
      this.onCancel();
      this.hide();
    });

    overlay.addEventListener('click', (e) => {
      if (e.target === overlay) {
        this.onCancel();
        this.hide();
      }
    });

    this.form.addEventListener('submit', (e) => {
      e.preventDefault();
      this.handleSave();
    });
  }

  handleSave() {
    const formData = new FormData(this.form);
    const updates = {};

    // Get all form values
    for (const [key, value] of formData.entries()) {
      if (key === 'choices') {
        // Parse choices
        const choices = value.split('\n').filter(line => line.trim()).map(line => {
          const parts = line.split('|');
          if (parts.length === 2) {
            return { value: parts[0].trim(), text: parts[1].trim() };
          }
          return { value: line.trim(), text: line.trim() };
        });
        if (choices.length > 0) {
          updates.choices = choices;
        }
      } else if (key === 'rateMax') {
        updates[key] = parseInt(value, 10);
      } else if (value.trim()) {
        updates[key] = value.trim();
      }
    }

    // Handle checkboxes
    ['isRequired', 'startWithNewLine', 'hasOther'].forEach(field => {
      const checkbox = this.form.querySelector(`[name="${field}"]`);
      if (checkbox) {
        updates[field] = checkbox.checked;
      }
    });

    this.onSave(updates);
    this.hide();
  }

  getTypeSpecificFields() {
    if (!this.element) {return '';}

    switch (this.element.type) {
      case 'text':
      case 'comment':
        return `
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Placeholder</label>
                        <input type="text" name="placeholder" class="form-control" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                    </div>
                `;

      case 'radiogroup':
      case 'checkbox':
      case 'dropdown':
        return `
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Choices (one per line)</label>
                        <textarea name="choices" class="form-control" rows="5" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;"></textarea>
                        <small style="color: #6c757d;">Format: value|display text (or just value)</small>
                    </div>
                    ${
                      this.element.type === 'radiogroup' || this.element.type === 'checkbox'
                        ? `
                        <div class="form-group" style="margin-bottom: 20px;">
                            <label style="display: flex; align-items: center;">
                                <input type="checkbox" name="hasOther" style="margin-right: 8px;">
                                Include "Other" option
                            </label>
                        </div>
                    `
                        : ''
                    }`;

      case 'rating':
        return `
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Rate Max</label>
                        <input type="number" name="rateMax" class="form-control" min="1" max="10" value="5" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                    </div>
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Min Rate Description</label>
                        <input type="text" name="minRateDescription" class="form-control" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                    </div>
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Max Rate Description</label>
                        <input type="text" name="maxRateDescription" class="form-control" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                    </div>
                `;

      case 'boolean':
        return `
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Label True</label>
                        <input type="text" name="labelTrue" class="form-control" placeholder="Yes" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                    </div>
                    <div class="form-group" style="margin-bottom: 20px;">
                        <label style="display: block; margin-bottom: 5px; font-weight: 500;">Label False</label>
                        <input type="text" name="labelFalse" class="form-control" placeholder="No" style="width: 100%; padding: 8px 12px; border: 1px solid #ced4da; border-radius: 4px;">
                    </div>
                `;

      default:
        return '';
    }
  }

  populateForm() {
    if (!this.element || !this.form) {return;}

    // Populate basic fields
    const fields = ['name', 'title', 'description', 'placeholder', 'visibleIf', 'enableIf'];
    fields.forEach(field => {
      const input = this.form.querySelector(`[name="${field}"]`);
      if (input && this.element[field]) {
        input.value = this.element[field];
      }
    });

    // Populate checkboxes
    const checkboxes = ['isRequired', 'startWithNewLine', 'hasOther'];
    checkboxes.forEach(field => {
      const checkbox = this.form.querySelector(`[name="${field}"]`);
      if (checkbox && this.element[field]) {
        checkbox.checked = true;
      }
    });

    // Populate type-specific fields
    if (this.element.choices) {
      const choicesTextarea = this.form.querySelector('[name="choices"]');
      if (choicesTextarea) {
        const choicesText = this.element.choices.map(choice => {
          if (typeof choice === 'string') {return choice;}
          return choice.value === choice.text ? choice.value : `${choice.value}|${choice.text}`;
        }).join('\n');
        choicesTextarea.value = choicesText;
      }
    }

    if (this.element.rateMax) {
      const rateMaxInput = this.form.querySelector('[name="rateMax"]');
      if (rateMaxInput) {
        rateMaxInput.value = this.element.rateMax;
      }
    }

    ['minRateDescription', 'maxRateDescription', 'labelTrue', 'labelFalse'].forEach(field => {
      const input = this.form.querySelector(`[name="${field}"]`);
      if (input && this.element[field]) {
        input.value = this.element[field];
      }
    });
  }
}

