import { jest } from '@jest/globals';
import { debounce } from '../../src/utils/debounce.js';

// Tell Jest to use fake timers
jest.useFakeTimers();

describe('debounce', () => {
  let mockFunction;
  let debouncedFunction;

  beforeEach(() => {
    // Clear all timers before each test
    jest.clearAllTimers();
    // Create a fresh mock function for each test
    mockFunction = jest.fn();
  });

  afterEach(() => {
    // Clean up any remaining timers
    jest.clearAllTimers();
  });

  it('should create a debounced function', () => {
    debouncedFunction = debounce(mockFunction, 100);
    expect(typeof debouncedFunction).toBe('function');
  });

  it('should not call the function immediately', () => {
    debouncedFunction = debounce(mockFunction, 100);
    debouncedFunction();
    expect(mockFunction).not.toHaveBeenCalled();
  });

  it('should call the function after the delay', () => {
    debouncedFunction = debounce(mockFunction, 100);
    debouncedFunction('arg1', 'arg2');
    
    // Fast-forward time by 100ms
    jest.advanceTimersByTime(100);
    
    expect(mockFunction).toHaveBeenCalledTimes(1);
    expect(mockFunction).toHaveBeenCalledWith('arg1', 'arg2');
  });

  it('should only call the function once for multiple rapid calls', () => {
    debouncedFunction = debounce(mockFunction, 100);
    
    // Call the debounced function multiple times rapidly
    debouncedFunction('call1');
    debouncedFunction('call2');
    debouncedFunction('call3');
    debouncedFunction('call4');
    
    // Fast-forward time by 100ms
    jest.advanceTimersByTime(100);
    
    // Should only be called once with the last arguments
    expect(mockFunction).toHaveBeenCalledTimes(1);
    expect(mockFunction).toHaveBeenCalledWith('call4');
  });

  it('should reset the timer on subsequent calls', () => {
    debouncedFunction = debounce(mockFunction, 100);
    
    debouncedFunction('first');
    
    // Advance timer by 50ms (not enough to trigger)
    jest.advanceTimersByTime(50);
    expect(mockFunction).not.toHaveBeenCalled();
    
    // Call again, which should reset the timer
    debouncedFunction('second');
    
    // Advance timer by another 50ms (still not enough from the second call)
    jest.advanceTimersByTime(50);
    expect(mockFunction).not.toHaveBeenCalled();
    
    // Advance timer by another 50ms (now 100ms from the second call)
    jest.advanceTimersByTime(50);
    expect(mockFunction).toHaveBeenCalledTimes(1);
    expect(mockFunction).toHaveBeenCalledWith('second');
  });

  it('should allow multiple independent debounced functions', () => {
    const mockFunction2 = jest.fn();
    const debouncedFunction1 = debounce(mockFunction, 100);
    const debouncedFunction2 = debounce(mockFunction2, 200);
    
    debouncedFunction1('func1');
    debouncedFunction2('func2');
    
    // Advance timer by 100ms
    jest.advanceTimersByTime(100);
    
    // Only the first function should have been called
    expect(mockFunction).toHaveBeenCalledTimes(1);
    expect(mockFunction).toHaveBeenCalledWith('func1');
    expect(mockFunction2).not.toHaveBeenCalled();
    
    // Advance timer by another 100ms (total 200ms)
    jest.advanceTimersByTime(100);
    
    // Now both functions should have been called
    expect(mockFunction2).toHaveBeenCalledTimes(1);
    expect(mockFunction2).toHaveBeenCalledWith('func2');
  });

  it('should handle zero delay', () => {
    debouncedFunction = debounce(mockFunction, 0);
    debouncedFunction('immediate');
    
    // Even with 0 delay, it should still be async
    expect(mockFunction).not.toHaveBeenCalled();
    
    // Advance timers by any amount
    jest.advanceTimersByTime(0);
    
    expect(mockFunction).toHaveBeenCalledTimes(1);
    expect(mockFunction).toHaveBeenCalledWith('immediate');
  });

  it('should preserve the context (this)', () => {
    const context = { value: 42 };
    const mockFunctionWithContext = jest.fn(function() {
      return this.value;
    });
    
    debouncedFunction = debounce(mockFunctionWithContext, 100);
    debouncedFunction.call(context);
    
    jest.advanceTimersByTime(100);
    
    expect(mockFunctionWithContext).toHaveBeenCalledTimes(1);
    expect(mockFunctionWithContext.mock.instances[0]).toBe(context);
  });
});

import HtmlEscape from '../../src/utils/htmlEscape.js';

describe('htmlEscape utilities', () => {
  describe('HtmlEscape.escape', () => {
    it('should escape HTML special characters', () => {
      const input = '<div class="test">Hello & "World"</div>';
      const expected = '&lt;div class=&quot;test&quot;&gt;Hello &amp; &quot;World&quot;&lt;/div&gt;';
      expect(HtmlEscape.escape(input)).toBe(expected);
    });

    it('should escape all HTML entities', () => {
      const input = '< > & " \'';
      const expected = '&lt; &gt; &amp; &quot; &#39;';
      expect(HtmlEscape.escape(input)).toBe(expected);
    });

    it('should handle empty strings', () => {
      expect(HtmlEscape.escape('')).toBe('');
    });

    it('should handle strings without special characters', () => {
      const input = 'Hello World 123';
      expect(HtmlEscape.escape(input)).toBe(input);
    });

    it('should handle null and undefined gracefully', () => {
      expect(HtmlEscape.escape(null)).toBe('');
      expect(HtmlEscape.escape(undefined)).toBe('');
    });

    it('should convert non-string values to strings', () => {
      expect(HtmlEscape.escape(123)).toBe('123');
      expect(HtmlEscape.escape(true)).toBe('true');
      expect(HtmlEscape.escape(false)).toBe('false');
    });

    it('should handle script tags', () => {
      const input = '<script>alert("XSS")</script>';
      const expected = '&lt;script&gt;alert(&quot;XSS&quot;)&lt;/script&gt;';
      expect(HtmlEscape.escape(input)).toBe(expected);
    });

    it('should handle multiple occurrences', () => {
      const input = '<p>First & Second & Third</p>';
      const expected = '&lt;p&gt;First &amp; Second &amp; Third&lt;/p&gt;';
      expect(HtmlEscape.escape(input)).toBe(expected);
    });

    it('should handle nested quotes', () => {
      const input = `<div onclick="alert('Hello')">Click me</div>`;
      const expected = `&lt;div onclick=&quot;alert(&#39;Hello&#39;)&quot;&gt;Click me&lt;/div&gt;`;
      expect(HtmlEscape.escape(input)).toBe(expected);
    });

    it('should handle unicode characters', () => {
      const input = '<div>Hello 👋 & "世界"</div>';
      const expected = '&lt;div&gt;Hello 👋 &amp; &quot;世界&quot;&lt;/div&gt;';
      expect(HtmlEscape.escape(input)).toBe(expected);
    });
  });

  describe('HtmlEscape.unescape', () => {
    it('should unescape HTML entities', () => {
      const input = '&lt;div class=&quot;test&quot;&gt;Hello &amp; &quot;World&quot;&lt;/div&gt;';
      const expected = '<div class="test">Hello & "World"</div>';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });

    it('should unescape all HTML entities', () => {
      const input = '&lt; &gt; &amp; &quot; &#39;';
      const expected = '< > & " \'';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });

    it('should handle empty strings', () => {
      expect(HtmlEscape.unescape('')).toBe('');
    });

    it('should handle strings without entities', () => {
      const input = 'Hello World 123';
      expect(HtmlEscape.unescape(input)).toBe(input);
    });

    it('should handle null and undefined gracefully', () => {
      expect(HtmlEscape.unescape(null)).toBe('');
      expect(HtmlEscape.unescape(undefined)).toBe('');
    });

    it('should convert non-string values to strings', () => {
      expect(HtmlEscape.unescape(123)).toBe('123');
      expect(HtmlEscape.unescape(true)).toBe('true');
      expect(HtmlEscape.unescape(false)).toBe('false');
    });

    it('should handle escaped script tags', () => {
      const input = '&lt;script&gt;alert(&quot;XSS&quot;)&lt;/script&gt;';
      const expected = '<script>alert("XSS")</script>';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });

    it('should handle multiple occurrences', () => {
      const input = '&lt;p&gt;First &amp; Second &amp; Third&lt;/p&gt;';
      const expected = '<p>First & Second & Third</p>';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });

    it('should handle numeric entities', () => {
      const input = '&#39;Hello&#39;';
      const expected = '\'Hello\'';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });

    it('should handle unicode with entities', () => {
      const input = '&lt;div&gt;Hello 👋 &amp; &quot;世界&quot;&lt;/div&gt;';
      const expected = '<div>Hello 👋 & "世界"</div>';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });

    it('should handle partial entities (invalid HTML)', () => {
      const input = '&lt incomplete &gt;';
      // Should only unescape complete entities
      expect(HtmlEscape.unescape(input)).toBe('&lt incomplete >');
    });

    it('should handle mixed escaped and unescaped content', () => {
      const input = 'Normal text &lt;b&gt;bold&lt;/b&gt; more text';
      const expected = 'Normal text <b>bold</b> more text';
      expect(HtmlEscape.unescape(input)).toBe(expected);
    });
  });

  describe('HtmlEscape.escape and HtmlEscape.unescape roundtrip', () => {
    it('should properly roundtrip simple HTML', () => {
      const original = '<p>Hello & "World"</p>';
      const escaped = HtmlEscape.escape(original);
      const unescaped = HtmlEscape.unescape(escaped);
      expect(unescaped).toBe(original);
    });

    it('should properly roundtrip complex HTML', () => {
      const original = `<div class="container" data-value='test'>
        <h1>Title & Subtitle</h1>
        <p>Content with "quotes" and 'apostrophes'</p>
        <script>alert("Hello")</script>
      </div>`;
      const escaped = HtmlEscape.escape(original);
      const unescaped = HtmlEscape.unescape(escaped);
      expect(unescaped).toBe(original);
    });

    it('should properly roundtrip empty and special cases', () => {
      const testCases = ['', ' ', '\n', '\t', '   spaces   '];
      testCases.forEach(original => {
        const escaped = HtmlEscape.escape(original);
        const unescaped = HtmlEscape.unescape(escaped);
        expect(unescaped).toBe(original);
      });
    });
  });
});

import { NotificationManager } from '../../src/utils/notifications.js';

describe('NotificationManager', () => {
  let container;
  let notificationManager;

  beforeEach(() => {
    // Create a container element for notifications
    container = document.createElement('div');
    container.id = 'test-container';
    document.body.appendChild(container);
    
    // Create a new instance for each test
    notificationManager = new NotificationManager('test-container');
  });

  afterEach(() => {
    // Clean up the DOM
    document.body.removeChild(container);
    // Clear any remaining timeouts
    jest.clearAllTimers();
  });

  describe('constructor', () => {
    it('should create a notification container', () => {
      const notificationContainer = container.querySelector('.notification-container');
      expect(notificationContainer).toBeInTheDocument();
    });

    it('should use default container ID if none provided', () => {
      const defaultManager = new NotificationManager();
      const defaultContainer = document.querySelector('#app .notification-container');
      expect(defaultContainer).toBeInTheDocument();
      // Clean up
      defaultContainer?.remove();
    });

    it('should create app container if it does not exist', () => {
      const customManager = new NotificationManager('non-existent-container');
      const appContainer = document.querySelector('#app');
      expect(appContainer).toBeInTheDocument();
      const notificationContainer = appContainer.querySelector('.notification-container');
      expect(notificationContainer).toBeInTheDocument();
      // Clean up
      appContainer?.remove();
    });
  });

  describe('show', () => {
    it('should display a success notification', () => {
      notificationManager.show('Success message', 'success');
      
      const notification = container.querySelector('.notification.success');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Success message');
    });

    it('should display an error notification', () => {
      notificationManager.show('Error message', 'error');
      
      const notification = container.querySelector('.notification.error');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Error message');
    });

    it('should display an info notification', () => {
      notificationManager.show('Info message', 'info');
      
      const notification = container.querySelector('.notification.info');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Info message');
    });

    it('should display a warning notification', () => {
      notificationManager.show('Warning message', 'warning');
      
      const notification = container.querySelector('.notification.warning');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Warning message');
    });

    it('should default to info type if type is not specified', () => {
      notificationManager.show('Default message');
      
      const notification = container.querySelector('.notification.info');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Default message');
    });

    it('should display multiple notifications', () => {
      notificationManager.show('First message', 'success');
      notificationManager.show('Second message', 'error');
      notificationManager.show('Third message', 'info');
      
      const notifications = container.querySelectorAll('.notification');
      expect(notifications).toHaveLength(3);
      expect(notifications[0]).toHaveClass('success');
      expect(notifications[1]).toHaveClass('error');
      expect(notifications[2]).toHaveClass('info');
    });

    it('should add show class after a brief delay', () => {
      jest.useFakeTimers();
      
      notificationManager.show('Test message', 'success');
      
      const notification = container.querySelector('.notification');
      expect(notification).not.toHaveClass('show');
      
      // Fast forward to trigger the show class
      jest.advanceTimersByTime(10);
      
      expect(notification).toHaveClass('show');
      
      jest.useRealTimers();
    });

    it('should auto-dismiss notification after duration', () => {
      jest.useFakeTimers();
      
      notificationManager.show('Test message', 'success', 3000);
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      
      // Fast forward past the duration
      jest.advanceTimersByTime(3000);
      
      expect(notification).not.toHaveClass('show');
      
      // Fast forward to complete removal
      jest.advanceTimersByTime(300);
      
      expect(notification).not.toBeInTheDocument();
      
      jest.useRealTimers();
    });

    it('should use default duration if not specified', () => {
      jest.useFakeTimers();
      
      notificationManager.show('Test message', 'success');
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      
      // Fast forward past the default duration (5000ms)
      jest.advanceTimersByTime(5000);
      
      expect(notification).not.toHaveClass('show');
      
      jest.useRealTimers();
    });

    it('should handle empty message', () => {
      notificationManager.show('', 'success');
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('');
    });

    it('should escape HTML in messages', () => {
      notificationManager.show('<script>alert("XSS")</script>', 'error');
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      expect(notification.textContent).toBe('<script>alert("XSS")</script>');
      expect(notification.innerHTML).not.toContain('<script>');
    });
  });

  describe('success', () => {
    it('should show a success notification', () => {
      notificationManager.success('Success!');
      
      const notification = container.querySelector('.notification.success');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Success!');
    });

    it('should use custom duration', () => {
      jest.useFakeTimers();
      
      notificationManager.success('Success!', 1000);
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      
      jest.advanceTimersByTime(1000);
      expect(notification).not.toHaveClass('show');
      
      jest.useRealTimers();
    });
  });

  describe('error', () => {
    it('should show an error notification', () => {
      notificationManager.error('Error!');
      
      const notification = container.querySelector('.notification.error');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Error!');
    });

    it('should use custom duration', () => {
      jest.useFakeTimers();
      
      notificationManager.error('Error!', 2000);
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      
      jest.advanceTimersByTime(2000);
      expect(notification).not.toHaveClass('show');
      
      jest.useRealTimers();
    });
  });

  describe('info', () => {
    it('should show an info notification', () => {
      notificationManager.info('Info!');
      
      const notification = container.querySelector('.notification.info');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Info!');
    });

    it('should use custom duration', () => {
      jest.useFakeTimers();
      
      notificationManager.info('Info!', 1500);
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      
      jest.advanceTimersByTime(1500);
      expect(notification).not.toHaveClass('show');
      
      jest.useRealTimers();
    });
  });

  describe('warning', () => {
    it('should show a warning notification', () => {
      notificationManager.warning('Warning!');
      
      const notification = container.querySelector('.notification.warning');
      expect(notification).toBeInTheDocument();
      expect(notification).toHaveTextContent('Warning!');
    });

    it('should use custom duration', () => {
      jest.useFakeTimers();
      
      notificationManager.warning('Warning!', 2500);
      
      const notification = container.querySelector('.notification');
      expect(notification).toBeInTheDocument();
      
      jest.advanceTimersByTime(2500);
      expect(notification).not.toHaveClass('show');
      
      jest.useRealTimers();
    });
  });

  describe('positioning', () => {
    it('should stack multiple notifications vertically', () => {
      notificationManager.show('First', 'success');
      notificationManager.show('Second', 'error');
      notificationManager.show('Third', 'info');
      
      const notifications = container.querySelectorAll('.notification');
      const positions = Array.from(notifications).map(n => n.getBoundingClientRect());
      
      // Check that each notification is below the previous one
      for (let i = 1; i < positions.length; i++) {
        expect(positions[i].top).toBeGreaterThan(positions[i - 1].bottom);
      }
    });
  });

  describe('notification removal', () => {
    it('should remove notification when clicking close button', () => {
      notificationManager.show('Closeable message', 'info');
      
      const notification = container.querySelector('.notification');
      const closeButton = notification.querySelector('.close-button');
      
      expect(notification).toBeInTheDocument();
      
      // Simulate click on close button
      closeButton.click();
      
      // Wait for removal animation
      setTimeout(() => {
        expect(notification).not.toBeInTheDocument();
      }, 300);
    });

    it('should handle multiple notifications being removed', () => {
      jest.useFakeTimers();
      
      notificationManager.show('First', 'success', 1000);
      notificationManager.show('Second', 'error', 2000);
      notificationManager.show('Third', 'info', 3000);
      
      expect(container.querySelectorAll('.notification')).toHaveLength(3);
      
      // First notification should be removed after 1000ms
      jest.advanceTimersByTime(1300);
      expect(container.querySelectorAll('.notification')).toHaveLength(2);
      
      // Second notification should be removed after 2000ms
      jest.advanceTimersByTime(1000);
      expect(container.querySelectorAll('.notification')).toHaveLength(1);
      
      // Third notification should be removed after 3000ms
      jest.advanceTimersByTime(1000);
      expect(container.querySelectorAll('.notification')).toHaveLength(0);
      
      jest.useRealTimers();
    });
  });
});

import { defineConfig } from 'vite';
import { resolve } from 'path';
import { visualizer } from 'rollup-plugin-visualizer';

// Vite configuration for Form Builder
export default defineConfig({
  // Base public path
  base: '/',
  
  // Source root
  root: '.', 
  
  // Public directory
  publicDir: 'public',
  
  // Development server configuration
  server: {
    port: 3000,
    open: true,
    cors: true,
    
    // Proxy API requests to Cloudflare Workers
    proxy: {
      '/api': {
        target: 'http://localhost:8787',
        changeOrigin: true,
        secure: false
      }
    }
  },
  
  // Build configuration
  build: {
    // Output directory
    outDir: 'dist',
    
    // Asset directory within output
    assetsDir: 'assets',
    
    // Enable source maps for production
    sourcemap: true,
    
    // Minification options
    minify: 'terser',
    terserOptions: {
      compress: {
        drop_console: false, // Keep console logs for debugging
        drop_debugger: true
      }
    },
    
    // Rollup options
    rollupOptions: {
      // Entry points
      input: {
        main: resolve(__dirname, 'public/index.html'),
        builder: resolve(__dirname, 'public/builder.html'),
        'edit-forms': resolve(__dirname, 'public/edit-forms.html'),
        'template-selection': resolve(__dirname, 'public/template-selection.html'),
        'template-preview': resolve(__dirname, 'public/template-preview.html')
      },
      
      // Output configuration
      output: {
        // Entry file names
        entryFileNames: 'assets/[name].[hash].js',
        
        // Chunk file names
        chunkFileNames: 'assets/[name].[hash].js',
        
        // Asset file names
        assetFileNames: (assetInfo) => {
          const info = assetInfo.name.split('.');
          const ext = info[info.length - 1];
          
          if (/\.(css|scss)$/.test(assetInfo.name)) {
            return 'assets/css/[name].[hash].[ext]';
          }
          
          if (/\.(png|jpe?g|gif|svg|ico|webp)$/.test(assetInfo.name)) {
            return 'assets/images/[name].[hash].[ext]';
          }
          
          if (/\.(woff2?|eot|ttf|otf)$/.test(assetInfo.name)) {
            return 'assets/fonts/[name].[hash].[ext]';
          }
          
          return 'assets/[name].[hash].[ext]';
        },
        
        // Manual chunks for optimal code splitting
        manualChunks: {
